// GENERATED by scripts/extract-citations.mjs. Do not hand-edit.
// spec-v1185: literal citation strings from bespoke renderers, read by
// mcp/catalog.mjs as the citation.text for tiles whose citation is not on a
// render.schema. Regenerate with `node scripts/extract-citations.mjs --write`.
export const RENDERER_CITATIONS = {
  "abatement-containment": "Citation: EPA NESHAP 40 CFR 61 Subpart M (asbestos), EPA RRP 40 CFR 745 (lead), and OSHA 1926.1101 / 1926.62 by name. poly = (floor x layers + wall x layers) x 1.10; req cfm = volume x ACH / 60; bags from debris volume. A licensed / certified contractor governs.",
  "abrasive-blast": "Citation: SSPC / AMPP surface-preparation (SP) specifications and the nozzle manufacturer's air / abrasive chart by name. cfm scales from the representative 100 psi value; compressor ~4 cfm per hp; abrasive = area x lb/ft^2. The nozzle chart governs.",
  "adpi-diffuser-selection": "Citation: ASHRAE Handbook -- Fundamentals, Space Air Diffusion, ADPI Selection Guide (throw per ASHRAE Standard 70, ADPI per Standard 113; the Miller / Nevins Kansas State research). T/L predicts the Air Diffusion Performance Index; each outlet type and cooling load has a max-ADPI T/L and an above-threshold band. Isothermal catalog throw to the outlet's terminal velocity (50 fpm most; 100 fpm ceiling slots). Cooling mode; a selection aid, the manufacturer's data and the design engineer govern.",
  "air-receiver": "Citation: Public receiver formula V = (t * (C_demand - C_pump) * P_atm) / (P1 - P2). 1 ft^3 = 7.4805 gal.",
  "alternate-readability": "Citation: SMOG per McLaughlin, 'SMOG Grading: A New Readability Formula,' Journal of Reading 12:8 (1969). Coleman-Liau per Coleman and Liau, 'A computer readability formula designed for machine scoring,' Journal of Applied Psychology 60:2 (1975). Gunning Fog per Gunning, 'The Technique of Clear Writing' (1952). Automated Readability Index (ARI) per Smith and Senter, 'Automated Readability Index,' AMRL-TR-66-220, U.S. Air Force Aerospace Medical Research Laboratories (1967), public-domain federal publication.",
  "ambient-ampacity-adjust": "Citation: Per NEC 2023 310.15(B)(1) (ambient-temperature correction, 30 C table basis) and 310.15(C)(1) (more than three current-carrying conductors). Enter the base ampacity from your NEC 310.16 column; the correction factors are bundled de-facto reference. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents.",
  "amp-power-spl": "Citation: First-principles loudspeaker SPL from the 1 W / 1 m sensitivity reference, the 10log power term, and the inverse-square distance term (public; ANSI S1.1 decibel basis). Free-field estimate, room gain and power compression and excursion limits not modeled, the manufacturer max-SPL spec governs.",
  "anchor-embedment": "Citation: ld = T / (0.7 * sqrt(fc) * pi * d). Public bond strength formula.",
  "approach-delta-t": "Citation: Approach = T_sat_cond - T_outdoor; delta-T = T_return - T_supply. Bands from public engineering practice.",
  "area-by-coordinates": "Citation: Coordinate (shoelace) area per FM 5-233 Construction Surveying (public-domain US Government work) and standard surveying references. The recorded plat and surveyor of record govern; this is a field estimate.",
  "arrhenius-equation": "Citation: Arrhenius equation k = A exp(-Ea/RT), two-point form Ea = R ln(k2/k1)/(1/T1 - 1/T2), R = 8.314 J/(mol*K), temperatures in kelvin (Arrhenius, 1889). Q10 = (k2/k1)^(10/dT). Assumes a single mechanism over the interval. First principles.",
  "asymmetrical-fault-xr": "Citation: First-cycle fault asymmetry from X/R (IEEE C37 / NEMA AB-4 model): I_peak = sqrt(2) x I_sym x (1 + e^(-pi/(X/R))); asymmetrical RMS multiplier MF = sqrt(1 + 2 e^(-2 pi/(X/R))); I_asym = I_sym x MF. The asymmetrical first-cycle current, not the symmetrical RMS, is what a peak-withstand and bus bracing rating must survive. A design aid; the interrupting-duty rating and coordination study govern.",
  "awg-wire-geometry": "Citation: AWG geometric definition d = 0.005 x 92^((36 - n)/39) inches; circular mils = (d in mils)^2; metric area = pi (d/2)^2. Bare-conductor, solid-equivalent geometry. A reference; the manufacturer's conductor dimensions govern the built wire.",
  "axle-load-distribution": "Citation: Per the federal axle/gross weight limits - 23 CFR 658.17 (12,000 lb steer, 34,000 lb tandem, 80,000 lb gross) and the federal Bridge Formula, by name; lever-arm statics is public. Cross-references the bridge-formula tile. FMCSA enforces. Free at ecfr.gov.",
  "backflow": "Citation: Original plain-English summaries by the project author. Common backflow scenarios and typical preventer types.",
  "backflow-loss": "Citation: Manufacturer-published backflow preventer pressure-loss curves (Watts technical bulletins). Each result attributes the publishing manufacturer.",
  "bar-nesting": "Citation: one-dimensional cutting-stock packed by the first-fit-decreasing heuristic - sort the pieces longest first, place each in the first stick with room, open a new stick only when none fits. Kerf is charged per CUT, so a stick holding n pieces takes n-1 kerfs and a stick cut clean to its end takes one fewer than a stick with drop remaining. End trim is deducted from every stick before packing. First-fit-decreasing is a heuristic and not guaranteed optimal; the tile reports a material lower bound alongside its answer and says plainly when the packing is already at it. Not modeled: clamping and chuck loss, grain or finish direction, mill tolerance on stock length, reusable drop from earlier jobs, or nesting across different stock sizes. A material-ordering aid; the cut list and the shop govern.",
  "base-converter": "Citation: Positional-notation base conversion. Bases 2 through 36 (the maximum that fits in the [0-9] + [A-Z] digit alphabet). The tile uses standard JS parseInt and Number.toString(radix); behavior matches the IEEE-754 integer range (safe up to 2^53 - 1).",
  "baseboard-length-for-load": "Citation: manufacturer-attributed BTU-per-foot baseboard tables interpolated by water temperature, solved for length: length = target_load / (btu_per_ft x flow_factor). Attribution included with output. A sizing aid; the manufacturer rating and the room heat loss govern.",
  "baseboard-output": "Citation: Manufacturer-attributed BTU-per-foot baseboard tables interpolated by water temperature. Attribution included with output.",
  "battery-hydrogen-vent": "Citation: IEEE 1635 / IEEE-ASHRAE Guide 21 battery-room hydrogen ventilation (NFPA 855 4% LEL): Q = 0.054 x I x N cfm (N = individual 2 V CELLS, not jars), ACH = Q x 60 / room volume; holds the average hydrogen below 1% (75% margin under the 4% LEL). A design aid; the applicable code and room design govern.",
  "battery-vent-max-current": "Citation: IEEE 1635 / IEEE-ASHRAE Guide 21 battery-room hydrogen ventilation (NFPA 855 4% LEL), solved for the current: I_max = Q / (0.054 x N), N = individual 2 V CELLS (not jars). Holds the average hydrogen below 1% (75% margin under the 4% LEL). A design aid; the applicable code and room design govern.",
  "beam-reactions": "Citation: Statics / AISC Steel Construction Manual simple-beam diagram formulas (public; also in the AWC/NDS and any statics text). Simple-span pinned-roller only. Distinct from the beam-loading and joist-deflection tiles - this outputs reactions and moment for post/footing sizing, not stress or deflection.",
  "belt-hp-transmitted": "Citation: belt power P = (T1 - T2) V / 33000 hp with belt speed V = pi D N / 12 ft/min; only the effective tension Te = T1 - T2 does work. First-principles as in Machinery's Handbook / Gates Industrial Drive Design Manual, by name. A design aid; the belt/sheave ratings and wrap angle govern.",
  "bends-between-pulls": "Citation: NEC 2023 358.26 (EMT) and the matching .26 sections of the Chapter 3 raceway articles - no more than 360 degrees of total bend (four quarter bends) between pull points. Offsets and saddles count every bend they contain. The AHJ governs. Free at nfpa.org/freeaccess.",
  "blended-mortgage-rate": "Citation: blended mortgage rate (weighted-average cost of debt): blended = (bal1 x rate1 + bal2 x rate2) / (bal1 + bal2); monthly interest = (bal1 x rate1 + bal2 x rate2) / 1200. A balance-weighted snapshot that ignores differing terms and amortization; a variable second drifts. A comparison aid; the loan documents govern.",
  "bod-tss-loading-removal": "Citation: BOD/TSS mass loading and removal (the pounds formula, Metcalf & Eddy / operator practice): load (lb/day) = MGD x mg/L x 8.34, removal% = (influent - effluent) / influent x 100. An operations aid; the operator of record and the primacy agency govern compliance.",
  "bolt-circle": "Citation: Bolt-circle (circle-of-holes) layout - hole i sits at angle start + i x 360/N on a radius dia/2, so x = cx + R cos, y = cy + R sin; adjacent center-to-center chord = 2 R sin(180/N) - first-principles trigonometry (the circle-of-holes geometry as in Machinery's Handbook, by name). Confirm the pattern, datum, and tolerance against the drawing before drilling.",
  "box-fill": "Citation: per NEC 2023 §314.16 (volume allowances by conductor size; devices count twice the largest conductor; internal clamps count once). AHJ governs. Free at nfpa.org/freeaccess.",
  "break-even-occupancy": "Citation: Break-even occupancy = (operating expenses + annual debt service) / potential gross income, the occupancy at which the property exactly covers its costs. The cushion to the market/stabilized occupancy measures how much vacancy a deal can absorb before it goes cash-flow negative. The lender and the market govern the acceptable break-even.",
  "bridge-formula": "Citation: per 23 CFR 658.17 (Federal Bridge Formula). W = 500 (LN/(N-1) + 12N + 36) for any consecutive axle group N >= 2. State limits may be lower than federal. Free at ecfr.gov.",
  "brrrr-refi": "Citation: BRRRR cash-out refinance (real-estate investing practice): new loan = ARV x refi LTV, cash returned = new loan - existing payoff, capital left = total invested - cash returned, post-refi cash-on-cash = annual cash flow / capital left (infinite when all capital is recovered). The appraised ARV and the lender's LTV/seasoning rules govern. A screening aid; the actual refinance terms govern.",
  "buffer-tank-loop-credit": "Notice: A sizing aid, not the manufacturer's data; the equipment minimum-cycle data and the manufacturer govern. Citation: ASHRAE / Idronics (Caleffi) anti-short-cycle buffer-tank practice, by name. V_gross = on_time x (source_min - zone_load) / (500 x delta_T); loop_gal = 0.0408 x d^2 x L; V_net = max(0, V_gross - loop_gal). The loop credit is valid only for water fully coupled to the buffer (a common primary loop); the 500 factor is for water (adjust for glycol); existing distribution-piping water may cover part or all of the requirement.",
  "building-ua": "Citation: whole-building heat-loss coefficient UA = sum(A/R) + 1.08 x CFM, the infiltration conductance from 1.08 = 60 x 0.075 x 0.24, and the design load Q = UA x dT, ASHRAE Fundamentals / RESNET basis, by name. Sensible only; enter the natural infiltration cfm. An energy-audit aid, not a stamped Manual J.",
  "burial-depth-300-5": "Citation: NEC 2023 Table 300.5 (minimum cover requirements, 0 to 1000 volts), by name. Cover is measured to the top of the raceway/cable; the footnotes modify specific cells. The AHJ governs. Free at nfpa.org/freeaccess.",
  "cable-bend-radius": "Citation: Manufacturer technical bulletins (Southwire, AFC Cable, Belden, Corning). Minimum inside bend radius as a multiple of cable OD.",
  "capacitor-bank-for-resonance-order": "Citation: parallel-resonance order of a PF capacitor bank (IEEE 519 / IEEE 1531) solved for the bank: MVAR_cap = MVA_sc / h_target^2, the largest bank that keeps the resonant order at or above the target (a bigger bank lowers the order toward the low harmonics). A screening aid; a harmonic study governs.",
  "capacitor-discharge-time": "Citation: NEC 2023 460.6 discharge of stored energy: residual voltage to 50 V within 1 minute at or below 600 V (5 minutes above 600 V). V(t) = V0 e^(-t/RC); t = R C ln(V0/V_safe); R_max = t_limit / (C ln(V0/V_safe)); continuous burn = V0^2/R. The discharge means must be permanently or automatically connected. A design aid; the equipment listing and the AHJ govern.",
  "carbon-equivalent": "Citation: The IIW carbon-equivalent formula CE = C + Mn/6 + (Cr+Mo+V)/5 + (Ni+Cu)/15 as adopted in AWS D1.1 Structural Welding Code, by name; published formula. The output is a screening band, not a qualified welding procedure.",
  "category-weighted-grade": "Citation: Pure weighted-mean arithmetic; standard US letter bands (A >= 90, B >= 80, C >= 70, D >= 60). The instructor's gradebook governs; bands vary by school.",
  "center-pivot-runtime": "Citation: center-pivot application depth and runtime (USDA-NRCS center-pivot design; university extension), by name. hours = area x depth x 452.6 / flow; gross_gpm_per_acre = flow / area; net_depth = depth x efficiency / 100. The depth is set by the outer-tower speed; the outer spans cover more area, so the instantaneous application rate under an outer span can run off even when the daily depth is right. The pivot design and soil intake govern.",
  "cfu-plate-count": "Citation: Per the FDA Bacteriological Analytical Manual (BAM) Chapter 3 (Aerobic Plate Count) and APHA Standard Methods, by name; both public/free. Countable range 25-250 (FDA BAM) or 30-300 (APHA). Free at fda.gov/food/science-research-food/laboratory-methods-food.",
  "chamber-turnover": "Citation: ACH = (air mover total cfm + dehu cfm) * 60 / chamber volume. Companion to NAM sizing.",
  "chemical-feed-pump": "Citation: Pounds-formula basis (lb/day = MGD x mg/L x 8.34), standard AWWA / EPA water-operator practice, by name. Distinct from the coagulant-dose and pounds-formula tiles - this solves for the physical pump setting (% / GPD / mL per min). The operator of record and primacy agency govern.",
  "chi-square-gof": "Citation: chi-square = sum((observed - expected)^2 / expected) on k - 1 degrees of freedom; p-value from the chi-square CDF (regularized lower incomplete gamma, Numerical Recipes 6.2). Per OpenIntro Statistics Ch. 6. An expected count below 5 degrades the approximation. Free at openintro.org.",
  "chimney-draft": "Notice: A design aid, not a venting sign-off; the venting standard (NFPA 211) and the appliance instructions govern. Citation: ASHRAE Handbook HVAC Systems (chimney/vent) / NFPA 211 theoretical chimney draft, by name. D_t = 0.52 x B x H x (1/T_o - 1/T_m) with temperatures in Rankine and D_t in inches of water column; D_net = factor x D_t (factor 0.5 to 0.8). The barometric pressure must be altitude-corrected (thinner air at elevation cuts the draft), and T_m is the mean flue temperature, not the outlet.",
  "chimney-height-for-draft": "Notice: A design aid, not a venting sign-off; the venting standard (NFPA 211) and the appliance instructions govern. Citation: ASHRAE Handbook HVAC Systems (chimney/vent) / NFPA 211 theoretical chimney draft solved for the height: H = D_net_target / (net_factor x 0.52 x B x (1/T_o - 1/T_m)), temperatures in Rankine, D in inches of water column. Enter the NET draft the appliance needs (net_factor 0.5 to 0.8 accounts for flow and fitting losses). The barometric pressure must be altitude-corrected (thinner air at elevation cuts the draft), and T_m is the mean flue temperature, not the outlet.",
  "chlorine-decay": "Citation: first-order decay C(t) = C0 x exp(-k x t); time to target = ln(C0 / target) / k; booster distance = velocity x time-to-target (when a distribution velocity is entered). Per EPA 815-R-02-020 (Effects of Water Age on Distribution System Water Quality) and AWWA M14. EPA 40 CFR 141.74 governs the residual at the extremity. Free at epa.gov and awwa.org.",
  "chlorine-decay-constant": "Citation: first-order decay C(t) = C0 x exp(-k x t) solved for the rate constant, k = ln(C0 / C) / t, from an initial and a measured residual over an elapsed time (a distribution bottle test); half-life = ln(2) / k. Per EPA 815-R-02-020 (Effects of Water Age on Distribution System Water Quality) and AWWA M14. Free at epa.gov and awwa.org.",
  "cipolletti-weir": "Citation: Cipolletti (trapezoidal, 1H:4V) sharp-crested weir free-flow discharge Q = 3.367 x L x H^(3/2) (cfs, ft), per the USBR Water Measurement Manual (public domain) / King's Handbook of Hydraulics; the 4:1 side slopes compensate end-contraction so the full crest length is used. Requires a ventilated, free-flow, sharp-crested weir; the head is measured about 4H upstream. Free at usbr.gov/tsc/techreferences/mands/wmm.",
  "clarifier-area-for-loading": "Citation: Clarifier hydraulic loading (Ten States Standards / Metcalf & Eddy, Wastewater Engineering): surface overflow rate = flow/area, solved for the area: area = flow x 1e6 / SOR; equivalent circular diameter = sqrt(4 x area / pi). The state design criteria govern the limits. An operations aid; the operator of record and the primacy agency govern compliance.",
  "clarifier-surface-loading": "Citation: Clarifier hydraulic and solids loading (Ten States Standards / Metcalf & Eddy, Wastewater Engineering): surface overflow rate = flow/area (gpd/ft^2), weir overflow rate = flow/weir length (gpd/ft), solids loading = flow x MLSS x 8.34 / area (lb/ft^2/day). The state design criteria govern the limits. An operations aid; the operator of record and the primacy agency govern compliance.",
  "class-of-loss-screen": "Citation: IICRC S500 Class-of-loss definitions and the 24 in (2 ft) wick threshold, by name (not reproduced). A deterministic screen evaluated top-down: low-evaporation materials -> Class 4; wick > 2 ft or wall >= 40% -> Class 3; floor >= 40% -> Class 2; else Class 1. The inspector's classification and a moisture map govern; this proposes a Class and states the rationale.",
  "clausius-clapeyron": "Citation: Clausius-Clapeyron equation ln(P2/P1) = -(dHvap/R)(1/T2 - 1/T1), so dHvap = R ln(P2/P1)/(1/T1 - 1/T2), R = 8.314 J/(mol*K), temperatures in kelvin. Only the pressure ratio enters, so any consistent unit works. Assumes constant dHvap and an ideal vapor. First principles.",
  "co-air-free": "Notice: A safety-screening aid, not a certified combustion test; the analyzer and the manufacturer instructions govern. Citation: ANSI Z21 400 ppm air-free limit / BPI field practice air-free CO correction, by name. CO_air_free = CO_measured x 20.9 / (20.9 - measured_O2). As-measured CO is diluted by excess and dilution air and reads deceptively low; sample in the flue before the draft hood or dilution air. Limits: 400 ppm air-free (ANSI), under 100 ppm field target.",
  "coagulant-dose": "Citation: Pounds-formula equivalent for coagulants. lb/day = MGD × mg/L × 8.34. Product feed = pure lb / strength%. Product gal = product lb / (sg × 8.34). Metcalf & Eddy / AWWA M37 by name. Operator of record and primacy agency govern.",
  "color-codes": "Citation: Original plain-English summary of widely-used color conventions across NEC, IEC, gas piping, and ASME A13.1. Code documents referenced by name only.",
  "column-buckling-wood": "Citation: Per the NDS column-stability provisions (the Cp / Euler buckling basis), by name; reference design values user-supplied. Solid rectangular sawn lumber, c = 0.8. The IBC-adopted NDS edition governs. AWC publishes the NDS free read-only at awc.org.",
  "commercial-load-factor": "Citation: BOMA rentable/usable load factor (ANSI/BOMA Z65.1 Office Standard): rentable = usable x (1 + common_area_factor); load_factor = rentable / usable; annual_rent = base_rent x rentable; cost_per_usable = base_rent x load_factor. Rent is per rentable SF, which includes common areas the tenant cannot occupy. A cost-comparison aid; the measured BOMA areas and the lease govern.",
  "compare-refrigerants": "Citation: Manufacturer P-T table by attribution. ASHRAE 15-2022 governs refrigerant safety; manufacturer technical bulletin governs charge. Free at ashrae.org/technical-resources/standards-and-guidelines/read-only-versions-of-ashrae-standards.",
  "compound-curve": "Citation: compound circular curve geometry per AASHTO A Policy on Geometric Design of Highways and Streets (the Green Book) and Ghilani & Wolf, Elementary Surveying: each arc T = R tan(delta/2), L = R delta_rad; back tangent t1 = T1 + (T1+T2) sin(delta2)/sin(delta), forward tangent t2 = T2 + (T1+T2) sin(delta1)/sin(delta), delta = delta1 + delta2 (law of sines on the vertex triangle). Same-direction arcs; the engineer of record governs.",
  "compound-miter": "Citation: Compound-miter geometry for crown molding cut flat on the saw - miter (table) = atan(tan(corner/2) x sin(spring)) and bevel (blade tilt) = asin(cos(spring) x cos(corner/2)) - first-principles trigonometry, public domain. Reproduces the standard published compound-miter chart (38 deg spring / 90 deg corner = 31.62 miter / 33.86 bevel; 45 / 90 = 35.26 / 30.00). Cut a scrap test corner first.",
  "compressor-displacement": "Citation: reciprocating compressor theoretical displacement (ASHRAE Refrigeration; positive-displacement swept-volume geometry): displacement = (pi/4) x bore^2 x stroke x cylinders x RPM, / 1728 for CFM. This is the 100%-volumetric-efficiency ceiling; actual delivered volume = displacement x volumetric efficiency, which drops with compression ratio, leakage, and suction superheat. Reciprocating only. A comparison figure; the rated capacity at the operating condition governs.",
  "condenser-cop-for-heat-rejection": "Citation: total heat of rejection THR = Q_evap (1 + 1/COP) solved for the COP: COP = Q_evap / (THR - Q_evap); compressor work W_comp = THR - Q_evap. Hermetic motor heat inflates the measured THR and lowers the apparent COP. An engineering aid; the rated heat-of-rejection data govern.",
  "condenser-heat-rejection": "Citation: total heat of rejection THR = Q_evap (1 + 1/COP), compressor work W_comp = Q_evap/COP, and the ~1.25 comfort-cooling heat-rejection factor, by name. No heat-recovery split or hermetic motor heat. An engineering aid; the rated heat-of-rejection data govern.",
  "conductivity-from-tds": "Citation: conductivity from TDS (Standard Methods 2510 / operator practice), the inverse of the TDS estimate: EC (uS/cm at 25 C) = TDS (mg/L) / k, k commonly 0.55-0.75 by ion makeup. An estimate, not a measurement; calibrate k against a lab result. An operations aid; the operator of record and the primacy agency govern compliance.",
  "conduit-90-stub": "Citation: Conduit 90-degree stub, back-to-back, and segmented bends are first-principles geometry taught in the electrical apprenticeship; deduct/take-up figures (EMT 1/2 in ~5, 3/4 in ~6, 1 in ~8, 1-1/4 in ~11) are tool-specific - confirm against your bender per Ugly's Electrical References and NECA conduit-bending guidance by name. See the cable-bend-radius tile for minimum conductor bend radius. The AHJ governs.",
  "conduit-offset": "Citation: Conduit offset bending is first-principles trigonometry taught in the electrical apprenticeship; mark spacing and multipliers follow Ugly's Electrical References and NECA conduit-bending guidance by name. Bender deduct and shoe figures are tool-specific - confirm against your bender. See the cable-bend-radius tile for minimum conductor bend radius. The AHJ governs.",
  "confined-space-purge": "Notice: Departmental SOPs and incident command govern all confined-space and worker-safety operations. Citation: OSHA 1910.146 by section number only. Formula: t (min) = (V * N) / CFM.",
  "confined-space-vent": "Citation: Per OSHA 29 CFR 1910.146 (Permit-Required Confined Spaces) and NIOSH 80-106 (Working in Confined Spaces). Pre-entry atmospheric monitoring with a calibrated 4-gas meter is required by 1910.146(d)(5); ventilation does not substitute for the meter. AHJ governs. Free at ecfr.gov and at cdc.gov/niosh.",
  "containment-air-balance": "Citation: Public orifice-flow form Q (cfm) = 2610 * A (ft^2) * sqrt(delta_P (in wc)); leakage area entered in in^2 is converted to ft^2 (/144). Engineering practice.",
  "continuous-load-ocpd": "Citation: NEC 2023 210.20(A) / 215.3 overcurrent and 210.19(A) / 215.2(A) conductor rule (A_min = 1.25 x continuous + noncontinuous; 1.00 x for a 100%-rated assembly), device from the 240.6(A) standard ratings, by name. Before ampacity adjustment; equipment-specific rules are separate. The AHJ governs.",
  "cooling-tower": "Citation: Range = T_in - T_out; approach = T_out - T_wb; efficiency = range / (range + approach); heat rejection = gpm × 500 × range BTU/hr. Cooling Technology Institute (CTI) ATC-105 standard practice by name; the wet-bulb is the thermodynamic floor.",
  "cooling-water-makeup": "Citation: evaporation = recirculation x delta-T / 1000; blowdown = evaporation / (COC - 1); drift = recirculation x drift fraction; makeup = evaporation + blowdown + drift. Per the Cooling Technology Institute (CTI) publications and ASHRAE Systems and Equipment 2020 Ch. 40 (cooling towers). Free at cti.org and ashrae.org for the TOCs.",
  "cost-per-mile": "Citation: Cost-per-mile bucket methodology per ATRI (American Transportation Research Institute), 'An Analysis of the Operational Costs of Trucking', by name; arithmetic is public and all figures are user-supplied. Deadhead miles should be in the mileage base. Report free at truckingresearch.org.",
  "countersink-depth": "Citation: countersink diameter-to-depth (Machinery's Handbook countersinking): Z = (D_cs - d_hole) / (2 tan(angle/2)); full-cone travel = D_cs / (2 tan(angle/2)). 82 deg inch flat-head and 90 deg metric heads are not interchangeable. A setup aid; the tool geometry and the fastener callout govern.",
  "countersink-diameter-from-depth": "Citation: countersink depth-to-diameter (Machinery's Handbook countersinking) solved for the diameter: D_cs = 2 Z tan(angle/2) + d_hole. 82 deg inch flat-head and 90 deg metric heads are not interchangeable. A setup aid; the tool geometry and the fastener callout govern.",
  "crane-lift-quick": "Citation: ASME B30.5 by section. The crane manufacturer's load chart governs. The qualified lift director governs. Math aid only. Do not attempt a lift over 75% of chart capacity without a written critical-lift plan.",
  "cross-connection-air-gap": "Citation: IPC 608.15.1 / ASME A112.1.2 cross-connection air gap: minimum = 2x the effective opening diameter (never less than 1 in), or 3x within three diameters of a wall (never less than 1.5 in). The most positive backflow protection. A design aid, not a substitute for the plumbing code adopted by your AHJ.",
  "curve-number-runoff": "Citation: NRCS Curve Number runoff method (TR-55 Urban Hydrology for Small Watersheds, Chapter 2): S = 1000/CN - 10, Ia = 0.2 S, Q = (P - Ia)^2 / (P - Ia + S) for P > Ia (runoff depth, in). A public USDA/NRCS document. The curve number (from land cover and hydrologic soil group, TR-55 Table 2-2) and the rainfall depth are user-supplied; Ia = 0.2 S is the standard assumption. A design aid; the local drainage manual and the engineer of record govern.",
  "cutting-diameter-for-rpm": "Citation: Machining spindle speed RPM = 12 x SFM / (pi x diameter) - first-principles cutting geometry (the speeds-and-feeds method as in Machinery's Handbook, Industrial Press, by name) - solved for the diameter: diameter = 12 x SFM / (pi x RPM). The recommended surface speed (SFM) comes from the tool / material chart (user-supplied); the machine, fixturing, and rigidity govern the safe spindle speed.",
  "cutting-speed-rpm": "Citation: Machining spindle speed RPM = 12 x SFM / (pi x diameter) and feed rate IPM = RPM x flutes x chip load per tooth - first-principles cutting geometry (the speeds-and-feeds method as in Machinery's Handbook, Industrial Press, by name). The recommended surface speed (SFM) and chip load per tooth come from the tool / material chart (user-supplied); the machine, fixturing, and rigidity govern the safe spindle speed.",
  "deadhead-percent": "Citation: Freight-economics arithmetic; FMCSA/DOT terminology ('deadhead' = unladen movement), by name. Public definitions, no proprietary table. Rate per total mile is the effective loaded rate after absorbing empty miles.",
  "decimal-to-fraction": "Citation: Decimal-to-fraction tape-measure math - round the decimal to the nearest 1/N tick, reduce the fraction to lowest terms (GCD), and break it into feet-inches; the error is the rounded value minus the exact decimal - first-principles arithmetic, public domain. Binary (power-of-two) denominators are the tape-measure / machinist-scale standard.",
  "deck-beam-post": "Citation: per IRC 2021 §R507 (decks). Beam and post sized from first-principles mechanics (M = wL^2/8; L/360 deflection; NDS column C_P stability factor) with AWC NDS-2018 reference values bundled. Footing from the soil-bearing tile (IRC Table R401.4.1). Ledger fastener spacing per the public IRC Table R507.9.1.3(1). AHJ governs. Free at codes.iccsafe.org and awc.org.",
  "declining-balance-depreciation": "Citation: GAAP book depreciation - ASC 360 (Property, Plant, and Equipment), by name; distinct from the macrs-depreciation tile (IRS Pub 946 tax method). Accounting information, not advice; a CPA and current GAAP govern. Salvage is NOT subtracted before applying the DB rate.",
  "defensible-space": "Citation: CALFIRE / NFPA published guidance by name only. Original plain-English zone-based summary.",
  "design-flow-peaking": "Citation: sanitary design flow from population (Metcalf & Eddy, Wastewater Engineering / Ten States Standards): average daily flow = population x per-capita flow (gpcd); Harmon peaking factor PF = 1 + 14/(4 + sqrt(P)) and Gifft minimum ratio 0.2 x P^(1/6), P the population in thousands. Domestic sanitary flow only; infiltration/inflow and industrial load are added separately. The Harmon factor is drawn for populations of about 1,000 to 1,000,000. A design aid; Ten States Standards and the state design criteria and the engineer of record govern.",
  "differential-leveling": "Citation: height-of-instrument differential leveling HI = elev + BS, elev = HI - FS, elevation change sum(BS) - sum(FS), and the loop misclosure, per the standard surveying references (Ghilani/Wolf), by name. Arithmetic reduction only; the project control and specs govern.",
  "disinfection-ct": "Citation: Per USEPA Surface Water Treatment Rule Guidance Manual EPA 815-R-99-014 Table A-1 (free chlorine 3-log Giardia inactivation, ≤0.4 mg/L band, 6 temperature x 4 pH grid). 4-log virus pass inferred from the Giardia result (free-chlorine 3-log Giardia is more stringent than 4-log virus; no separate Table E-1 lookup). State primacy agency governs CT compliance; this tile is a planning check, not a compliance report. Free at epa.gov/dwreginfo/surface-water-treatment-rules.",
  "dividing-head": "Citation: Simple (plain) indexing on a 40:1 dividing head - turns per division = ratio / N, hole move = fraction x hole-circle count - first-principles arithmetic as in Machinery's Handbook (Industrial Press), by name; public domain. Differential and angular indexing are out of scope.",
  "dmx-planner": "Citation: USITT DMX-512A by name only. Each universe carries 512 channels.",
  "doubling-time": "Citation: Standard exponential-growth / population-doubling kinetics; Td = elapsed x ln(2) / ln(N / N0); mu = ln(N / N0) / elapsed; doublings = log2(N / N0). Doubling time is constant only during log (exponential) phase; a measurement spanning lag or stationary phase is meaningless. If N is an optical density, the ratio assumes OD stays proportional to cell count (fails at high density). The culture, medium, and conditions govern.",
  "draft-hood-dilution": "Notice: A diagnostic aid, not a certified combustion test; the analyzer and the manufacturer instructions govern. Citation: combustion-analysis practice, ambient-oxygen (20.9%) dilution mass balance, by name. dilution_ratio = (20.9 - O2_appliance) / (20.9 - O2_diluted); dilution_air_fraction = (O2_diluted - O2_appliance) / (20.9 - O2_appliance). The appliance O2 is sampled at the flue outlet before the draft hood, the diluted O2 in the vent connector after it. A CO reading in the diluted stream understates the real flue value by this ratio - sample the air-free CO before the draft hood.",
  "draft-lift-max": "Notice: A planning aid, not incident command. Citation: IFSTA / NWCG firefighter math altitude-corrected drafting maximum lift, by name. theoretical = 33.9 - elevation / 1000; attainable = factor x theoretical - suction losses (factor about 2/3). 1 in Hg of vacuum is about 1.13 ft of lift. A real pump cannot pull a perfect vacuum, so about two-thirds of theoretical (about 22.5 ft at sea level) is the ceiling, and every 1,000 ft of altitude shaves another foot; lift is set by atmosphere pushing water up the suction, not the pump.",
  "drill-point-angle-from-length": "Citation: Included point angle = 2 x atan( (diameter / 2) / point length ) - first-principles drill-point geometry (the standard 118-degree / 135-degree drill-point relation as in Machinery's Handbook, by name) solved for the angle. Geometry only; web thinning, drift, and the actual grind govern the drilled hole.",
  "drill-point-depth": "Citation: Drill point depth (tip allowance) = (diameter / 2) / tan(point angle / 2) - first-principles drill-point geometry (the standard 118-degree / 135-degree drill-point relation as in Machinery's Handbook, by name). Geometry only; web thinning, drift, and the machine depth stop govern the actual hole.",
  "drying-log": "Citation: Per IICRC S500-2021 (Standard for Professional Water Damage Restoration). IICRC certification governs. Boundary-humidity test - chamber GPP must trend below ambient GPP for drying to be in progress - is the public method; the standard governs acceptance. Free at iicrc.org for TOC; full standard is licensed.",
  "drying-times": "Citation: Original plain-English notes on typical drying behavior of common building materials.",
  "duct-friction-static": "Citation: Darcy-Weisbach with Swamee-Jain Colebrook approximation. ASHRAE Fundamentals duct-design chapter by name. Roughness from data/hvac/duct-roughness.json; fitting C_o from data/hvac/duct-fittings.json.",
  "duct-leakage": "Citation: SMACNA Duct Leakage Test Manual (3rd ed.) by name. ASHRAE 90.1-2022 §6.4.4.2 references the leakage-class system. Leakage scales with P^0.65 (the SMACNA leakage-class flow exponent).",
  "duct-sizing": "Citation: per IMC 2021 §603 and Darcy-Weisbach with Colebrook-White friction factor on standard galvanized-steel duct. Equivalent rectangular diameter per Huebscher. AHJ governs. Free at codes.iccsafe.org.",
  "duct-static-pressure-total": "Citation: Total external static pressure (TESP) roll-up - the sum of every external resistance the blower must overcome, checked against the blower fan table's rated static - per ACCA Manual D and the ASHRAE / SMACNA duct-design practice, by name; first-principles pressure accounting. Component drops are user-supplied from the manufacturer tables or a manometer; the blower fan table governs the delivered CFM.",
  "duct-velocity-pressure": "Citation: Per the ACCA Manual D / ASHRAE Fundamentals velocity-pressure relation V = 4005 x sqrt(VP) for standard air (0.075 lb/ft^3, sea level). At altitude or high temperature apply a density correction. Public duct-design relation.",
  "earthwork-end-area": "Citation: Average-end-area and prismoidal earthwork volumes per FHWA and state-DOT earthwork references and FM 5-233. Cut and fill are not netted here. The project earthwork report governs the paid quantity.",
  "economic-conductor-sizing": "Citation: Economic conductor sizing (first-principles I^2R): three-phase loss = 3 x I^2 x R; annual saving = (loss small - loss big) x hours x rate; payback = upsize cost / saving. Pays only on heavily loaded, long-hour feeders. A screening estimate; installed cost and the code minimum still govern.",
  "economizer-savings-hours": "Citation: ASHRAE sensible-heat relation Q = 1.08 * CFM * dT (public); air-side economizer changeover per ASHRAE Standard 90.1, by name. Estimate; design conditions govern. The 1.08 factor is sea-level standard air. ASHRAE 90.1 free read-only at ashrae.org.",
  "egress-capacity": "Citation: IBC 2021 §1005.3 (egress width = occupant load x capacity factor), §1006.2 / Table 1006.3.4 (exit-count thresholds: 1 up to 49, 2 to 500, 3 to 1000, 4 beyond), §1010.1.1 (32 in minimum door clear width). Capacity factors: sprinklered-with-alarm 0.2 in/occ stairs, 0.15 in/occ level; non-sprinklered 0.3 / 0.2. The reduced factors require the §1005.3.1/.2 sprinkler and emergency-communication conditions; the width is divided among the required exits; the door-leaf minimum and §1005.7 projections can govern. A design aid, not a code-official determination.",
  "emergency-contacts": "Citation: Universal U.S. emergency and locator numbers. No commercial directories.",
  "employer-payroll-tax": "Citation: FICA - 26 USC 3101/3111 and IRS Pub 15 (Circular E), rates 6.2% SS / 1.45% Medicare; FUTA - 26 USC 3301-3306, $7,000 wage base, 6.0% gross / 0.6% net with the state credit, IRS Form 940 - all by name. The SS wage base is indexed annually and user-supplied. Tax information, not advice. Free at irs.gov/forms-pubs and uscode.house.gov.",
  "eoq-order-quantity": "Citation: economic order quantity (Wilson EOQ inventory model): EOQ = sqrt(2 D S / H); orders/yr = D / EOQ; cycle = 365 / orders; total annual cost = sqrt(2 D S H). Minimizes ordering plus holding cost; the total-cost curve is flat near the minimum, so rounding to a case quantity barely hurts. No quantity discounts assumed. A planning aid; the demand and supplier terms govern.",
  "equipment-power-draw": "Citation: total draw = sum(quantity x nameplate amps); NEC 2023 210.20(A) limits a continuous load to 80% of the branch-circuit rating, so circuits required = ceil(total / (0.8 x breaker)). Nameplate amps are representative cut-sheet defaults (Phoenix / Dri-Eaz / B-Air class); the actual unit nameplate governs. Free at nfpa.org/freeaccess for NFPA 70 (NEC).",
  "equivalent-length": "Citation: Public engineering equivalent-length tables for common fittings and valves.",
  "estimated-tax": "Citation: IRC 6654 safe harbor; IRS Form 1040-ES quarterly schedule.",
  "ev-charger-load": "Citation: Per NEC 2023 Article 625 (EV charging). 625.41/625.42 classify the EVSE as a continuous load (circuit and breaker at 125% of nameplate); 625.42(A) covers energy-management sizing. Panel load per NEC 220.83/220.87. Conductor is a first-principles estimate (copper, 75 C, 30 C ambient); verify against NEC 310.16. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents.",
  "ev-charger-throttle": "Citation: NEC 2023 625.42(A) energy management systems (EVEMS) per-charger throttling: throttled = min(charger_max, aggregate_limit / active_chargers); full_rate_count = floor(aggregate_limit / charger_max); all_full = active_chargers x charger_max <= aggregate_limit. The EVEMS shares the aggregate limit equally among the active chargers, never above a charger's own maximum. This is the equal-share case; priority or round-robin schemes differ. The listed EVEMS must be enforced in hardware. The NEC and the AHJ govern.",
  "ev-load-management-ems": "Citation: NEC 2023 625.42(A) energy management systems (EVEMS) with the 2026 625.48 continuous factor: un-managed = 1.25 x per-charger x count; managed demand = 1.25 x EVEMS aggregate limit; freed headroom is the difference. A listed EVEMS lets the demand be the enforced aggregate limit, not the sum. The EVEMS must be listed and its setpoint enforced in hardware. The NEC and the AHJ govern.",
  "evaporation-load": "Citation: Per the IICRC S500 water-class framework and evaporation-load drying principle, by name (not reproduced); per-class load factors are editable field defaults the user tunes to the standard and the job. Class 4 (bound water) is non-linear in area. IICRC S500 governs.",
  "evaporator-td-dtd": "Citation: Evaporator design TD (DTD) = box temperature - saturated suction temperature, which sets the box humidity: a small TD holds high RH (produce), a large TD dries the air (packaged/frozen). A selection aid; the coil manufacturer's rating at the design TD governs.",
  "excavation-bench-plan": "Citation: Per OSHA 29 CFR 1926 Subpart P Appendix B (soil classification and slope) and §1926.652. Competent person on-site governs the final plan; this calculator outputs geometry only. Free at ecfr.gov.",
  "excess-air-o2": "Notice: A tuning aid, not a certified combustion test; the analyzer, the appliance, and the manufacturer instructions govern. Citation: ASME PTC 4.1 / combustion analysis practice excess air from flue-gas oxygen, by name. EA = O2 / (20.9 - O2) x 100, or from carbon dioxide EA = (CO2max / CO2 - 1) x 100 (CO2max ~ 11.7% natural gas, 13.7% propane, 15.3% #2 oil). The oxygen form assumes complete combustion, so measurable CO understates the excess air; a gas appliance targets about 3 to 4% oxygen (15 to 25% excess air).",
  "exchange-1031-timeline": "Citation: Treas. Reg. §1.1031(k)-1(b). The 45-day identification and 180-day exchange-close deadlines are calendar days (no business-day or federal-holiday rollover, in contrast to Fed.R.Civ.P. 6(a)). The replacement-property acquisition deadline is the earlier of 180 days or the taxpayer's federal return due date for the year of the sale. A qualified intermediary is required; attorney and tax professional govern.",
  "existing-load-220-87": "Citation: NEC 2023 220.87 (determining existing loads): basis = 125% of the maximum demand the utility metered (a year of data, or a 30-day recording); total = basis + new load; headroom = service rating - total. Void where the recorded data reflects on-site PV or peak-shaving that hides the true peak. A design aid; the AHJ and utility data govern.",
  "exterior-opening-protection": "Citation: IBC 2021 Table 705.8 (maximum area of exterior wall openings), keyed by fire separation distance and by protection / sprinkler status: <3 ft none; 3 to <5 ft 15% protected else none; 5 to <10 ft 25% / 10%; 10 to <15 ft 45% / 15%; 15 to <20 ft 75% / 25%; 20 to <25 ft no limit / 45%; 25 to <30 ft no limit / 70%; >=30 ft no limit. The FSD is measured per §705.3 to the lot line, the centerline of a public way, or an imaginary line between buildings; unprotected openings in a sprinklered building take the protected allowance (Note a). The §705.8.5 vertical-separation and §705.8.6 rules can further govern. A design aid, not a code-official determination.",
  "fall-arrest-anchorage": "Citation: OSHA 29 CFR 1926.502(d)(15) - anchorages used for attachment of personal fall arrest equipment shall be independent of any anchorage being used to support or suspend platforms and capable of supporting at least 5,000 pounds per employee attached, or shall be designed, installed, and used as part of a complete personal fall arrest system which maintains a safety factor of at least two, under the supervision of a qualified person. 29 CFR 1926.502(d)(16) - personal fall arrest systems shall limit maximum arresting force on an employee to 1,800 pounds when used with a body harness, limit the maximum deceleration distance an employee travels to 3.5 feet, be rigged such that an employee can neither free fall more than 6 feet nor contact any lower level, and have sufficient strength to withstand twice the potential impact energy of an employee free falling 6 feet or the free fall distance permitted by the system, whichever is less. US federal regulations in the public domain, quoted directly. Not checked: clearance below the anchor (see fall-arrest-clearance), body belts, horizontal lifelines, swing fall, snaphook compatibility and rollout, equipment ratings and inspection, post-fall rescue, or positioning and restraint anchorages. A screen, not a fall-protection plan; Subpart M, the manufacturer, and a qualified person govern.",
  "fall-arrest-clearance": "Notice: the equipment manufacturer's instructions and a qualified / competent person govern all fall protection per ANSI Z359.1 and OSHA 1926 Subpart M; a planning aid. Citation: required fall clearance RFC = free-fall distance + deceleration distance + worker height (D-ring to feet) + safety margin. Deceleration distance is capped at 3.5 ft for a shock-absorbing lanyard (Z359); the free-fall distance depends on the anchor position and connector length.",
  "fall-protection-clearance": "Citation: 29 CFR 1926.502 (fall protection systems criteria) by section. ANSI Z359 (Fall Protection) by name. Manufacturer connector-decel benchmarks in data/cross/fall-protection-benchmarks.json.",
  "fan-motor-bhp": "Citation: AMCA / ASHRAE fan-power relation BHP = (CFM * SP) / (6356 * eta) (public); standard motor HP sizes per NEMA MG 1, by name. Estimate; fan curve and motor data govern. TSP must be total (external + internal). Free principles in published HVAC texts.",
  "feeder-tap-rule": "Citation: Minimum feeder tap conductor ampacity under the 10-ft and 25-ft tap rules of NEC 240.21(B)(1) and (B)(2), by name: the tap must carry at least 1/10 (10 ft) or 1/3 (25 ft) of the feeder overcurrent device rating. A computational aid for the <= 1000 V case; the AHJ-adopted NEC edition and the design engineer govern, and the other conditions of 240.21(B) apply. Free at nfpa.org/freeaccess.",
  "fillet-weld-strength": "Citation: Fillet-weld effective throat (0.707*leg) and shear strength (allowable 0.30*F_Exx; LRFD 0.75*0.60*F_Exx) per AWS D1.1 Structural Welding Code - Steel and AISC 360 §J2, by name, with the minimum/maximum fillet sizes of AISC Table J2.4 and §J2.2b. The qualified WPS, the weld inspector, and the engineer of record govern; base-metal and matching-filler checks are the engineer's.",
  "final-grade-needed": "Citation: Standard weighted-average arithmetic (the common syllabus weighted-category convention); the instructor's gradebook governs. Pure public algebra.",
  "fine-aggregate-grading": "Citation: ASTM C33/C33M §6 fine-aggregate grading, by name. §6.1 limits (percent passing): 3/8 in 100, No.4 95-100, No.8 80-100, No.16 50-85, No.30 25-60, No.50 5-30, No.100 0-10. §6.2: not more than 45% passing any sieve and retained on the next consecutive sieve, and fineness modulus 2.3-3.1. The FM is delegated to the fineness-modulus tile so the two cannot drift. An acceptance screen on your own C136 sieve analysis; the sieve report and the mix design govern.",
  "fineness-modulus": "Citation: aggregate fineness modulus (ASTM C136 sieve analysis / C125 definition): FM = sum of the cumulative percent retained on the #4, #8, #16, #30, #50, #100 sieves / 100. ASTM C33 holds concrete sand to FM 2.3-3.1, and it should not drift more than 0.20 without a mix adjustment. A gradation summary, not the full sieve check. A QC aid; the sieve analysis and mix design govern.",
  "fire-friction": "Citation: National Fire Academy hydraulics training. FL = C * (Q/100)^2 * (L/100), Q in GPM, L in ft, FL in psi.",
  "fire-stream-reaction": "Citation: Per the IFSTA Pumping Apparatus Driver/Operator nozzle-reaction formulas: smooth bore NR = 1.57 * d^2 * NP; fog NR = 0.0505 * Q * sqrt(NP). Staffing thresholds (~60 lb one person, ~75 lb hose team) are advisory. AHJ and fire-officer judgment govern.",
  "fix-flip-profit": "Citation: Fix-and-flip profit and return (real-estate investing practice): all-in = purchase + rehab + holding + financing + selling (selling = ARV x selling%), profit = ARV - all-in, margin = profit/ARV, cash ROI = profit/cash, annualized = ROI x 12/months. The ARV must come from real comparable sales and the rehab from a real scope. A screening aid; the actual deal governs.",
  "flange-rating": "Citation: Flange pressure-temperature rating - the maximum allowable working pressure read from the ASME B16.5 table for the flange class, linearly interpolated between table temperatures, by name. The bundled ratings are Material Group 1.1 (carbon steel, e.g. A105); other material groups have their own tables. The value is the flange's rating - the weakest component (gasket, bolting, the mating pipe) can still govern the joint. The AHJ and the engineer of record govern.",
  "flash-gas-subcool": "Notice: A design aid, not a commissioning measurement; the manufacturer data and the actual refrigerant govern. Citation: ASHRAE Refrigeration Handbook / refrigerant piping guides liquid-line subcooling to prevent flash gas, by name. dP_lift = static_gradient x lift (0.43 psi/ft R-410A liquid); dP_total = dP_lift + friction; required_subcool = dP_total / pt_slope (~5 psi/degF R-410A near condensing). Techs often forget the vertical-lift column that dominates on a tall riser; measure subcooling at the metering device, add margin to the 8-12 F field target.",
  "flocculator-paddle-power": "Citation: Camp paddle flocculator power (water-treatment design practice), by name. v_tip = 2 x pi x radius x rpm / 60; v_rel = v_tip x (1 - k); P = 0.5 x Cd x 1.937 x area x v_rel^3 (ft-lb/s, x 1.35582 for W, / 550 for hp). The power goes as the cube of the relative velocity; the water slips (rotates with the paddles) so v_rel is only (1 - k) of the tip speed - ignoring the slip roughly doubles the power. Cd (about 1.8, 1.0 to 1.8 reported) and k (about 0.25, 0.25 to 0.40 reported) are user inputs because references disagree. This power feeds flocculation-g-value.",
  "flood-cut-quantity": "Citation: IICRC S500-2021 structural-removal principle by name (not reproduced). 4x8 drywall sheet = 32 ft^2. The cut height is a field decision driven by the highest moisture reading; Category 3 may require removing all wet porous material.",
  "flood-cut-takeoff": "Citation: Flood-cut demolition takeoff geometry per IICRC S500 practice, by name (not reproduced): cut a few inches above the highest moisture-meter reading. drywall_sf = perimeter * (cut_height_in/12) * faces; standard 4x8 board = 32 ft^2. The moisture meter governs the cut line, not a round number.",
  "floor-area-ratio": "Citation: floor area ratio (municipal zoning intensity measure): FAR = gross building floor area / lot area; max buildable floor area = FAR_limit x lot area; remaining = max buildable - existing. What counts as floor area (parking, basements, mechanical) varies by municipality; enter the gross figure the local code defines. A screening aid; the zoning ordinance and planning authority govern.",
  "foam-eductor-limit": "Notice: A planning aid, not incident command; the eductor manufacturer data governs. Citation: IFSTA / eductor manufacturer data (TFT/Elkhart) in-line foam eductor back-pressure limit, by name. max_back_pressure = 0.65 x inlet; FL_per_100 = C x (Q/100)^2; max_length = (max_back_pressure - nozzle - 0.434 x elevation) / FL_per_100 x 100. If the back-pressure exceeds about 65% of inlet the eductor stops drawing foam concentrate entirely (not less, none) while water keeps flowing; the eductor's rated flow must equal the nozzle's flow.",
  "footing-area": "Citation: per IRC 2021 §R401-R403 (foundations); allowable soil-bearing values per IBC 2021 Table 1806.2. required_area = load / allowable_bearing. AHJ governs. Free at codes.iccsafe.org.",
  "gas-pipe-max-flow": "Citation: Per the published Spitzglass low-pressure gas-flow equation (public engineering formula), solved for the flow - the capacity a bore carries within an allowable drop, the inverse of the gas-pipe pressure-drop tile and a longhand alternative to the NFPA 54 / IFGC capacity tables; NFPA 54 governs the installation. Inside diameter must be the actual bore. Free read-only at nfpa.org/freeaccess and codes.iccsafe.org.",
  "gas-pipe-pressure-drop": "Citation: Per the published Spitzglass low-pressure gas-flow equation (public engineering formula). The longhand alternative to the NFPA 54 / IFGC capacity tables that the gas-pipe-sizing tile uses; NFPA 54 governs the installation. Inside diameter must be the actual bore. Free read-only at nfpa.org/freeaccess and codes.iccsafe.org.",
  "gear-cascade": "Citation: First-principles gear math: stage ratio = N_out / N_in; overall ratio = product of stage ratios; RPM_out = RPM_in / overall; T_out = T_in * overall * efficiency^stages. AGMA 2000 classifies gear tolerance; the ratio math is standard-independent. Free at agma.org for the AGMA standards table of contents.",
  "generator-conductor-445": "Citation: NEC 2023 445.13(A) generator output conductors: required ampacity = 115% of the generator nameplate current (100% where the design prevents output above nameplate). The basis is the nameplate, not 125% of a computed load. The 110.14(C) termination limit and 310.15 adjustments still apply. A design aid; the AHJ governs.",
  "generator-fuel-runtime": "Citation: generator fuel runtime (first-principles): runtime = usable fuel / consumption; usable = tank x usable%. For a target duration, fuel = consumption x hours and the tank = fuel / usable%. Enter consumption from the genset data plate. A planning aid; the published fuel curve and the AHJ's fuel-storage rules govern.",
  "generator-motor-starting": "Citation: Generator sizing for motor starting per the published 30% voltage-dip criterion. NEMA MG-1 code-letter table.",
  "generator-sizing": "Citation: Continuous wattage = sum of running watts. Surge wattage = continuous + (largest motor's starting - running). Public engineering practice for portable generator sizing.",
  "geometry": "Citation: Standard plane and solid geometry. Ramanujan ellipse perimeter h = ((a-b)/(a+b))^2.",
  "gfci-afci-reference": "Citation: per NEC 2023 §210.8 (GFCI), §210.12 (AFCI), §406.4 (receptacle requirements). Original plain-English summaries by the project author; no code text reproduced. AHJ governs. Free at nfpa.org/freeaccess.",
  "gpa-calculator": "Citation: Standard US 4.0 / 5.0 GPA scale. Letter-to-point per the common registrar convention (A=4.0, A-=3.7, ..., F=0). Weighted GPA adds the per-course track bonus (honors +0.5, AP / IB / dual-enrollment +1.0) to passing grades only. School registrar governs final transcript; this is a planning aid only.",
  "grain-aeration-airflow": "Citation: stored-grain aeration fan airflow (MWPS / university extension; Shedd airflow-resistance curves), by name. required_cfm = rate_cfm_per_bu x bushels; cooling_hours = 15 / rate (per cooling front). Bands: aeration cooling 0.1-0.25 cfm/bu, natural-air drying 0.5-1.0 cfm/bu. Static pressure rises steeply with depth and fan power grows ~fourfold when the rate or depth doubles - read the fan curve at the actual static pressure. The fan selection and grain condition govern.",
  "grain-bin-capacity": "Citation: Bin geometry first-principles (cylinder + cone); bushels = ft^3 x 0.8036 (1 bushel = 1.2445 ft^3); test weights per USDA FGIS (Federal Grain Inspection Service) standards. Free at ams.usda.gov/services/grain-inspection.",
  "grain-drying-energy": "Citation: Grain drying energy (first-principles shrink + heat balance): water removed = weight x (Mi - Mf)/(100 - Mf), energy = water x ~1500 Btu/lb (dryer efficiency included), propane = energy / 91,500 Btu/gal. A planning aid; the dryer efficiency, fuel heat content, and market discount schedule govern.",
  "grain-shrink-moisture": "Citation: Grain drying shrink per the standard moisture-shrink relation used by USDA and land-grant extension: dry weight = wet weight x (100 - wet moisture)/(100 - market moisture), then a handling/invisible shrink deduction; net bushels = net weight / market test weight (56 lb corn, 60 wheat/soybeans). The buyer's contract, moisture discount schedule, and settlement scale govern.",
  "grains-removed": "Citation: First-principles psychrometric mass balance (7000 grains/lb; ~13.33 ft3/lb dry air at standard conditions). IICRC S500 grain-depression field method, by name. Distinct from the psychrometric and dehumidifier-sizing tiles - this verifies in-situ performance from measured inlet/outlet readings. IICRC S500 governs the drying plan.",
  "hand-signals": "Citation: Original plain-English summary of crane, excavator, flagger, and aircraft marshalling signals; agencies referenced by name only. No image reproduction.",
  "harmonic-resonance": "Citation: parallel-resonance order of a PF capacitor bank (IEEE 519 / IEEE 1531 harmonic filter and resonance guidance): h_resonant = sqrt(MVA_sc / MVAR_cap); flagged when within 0.5 of the 5th/7th/11th/13th. A bigger bank lowers the order toward the strong low harmonics. A screening aid; a harmonic study governs.",
  "header-sizing": "Citation: per IRC 2021 §R602.7 (headers). Member sized from first-principles simple-span mechanics (M = wL^2/8; sigma = M/S; delta = 5wL^4/384EI) with AWC NDS-2018 reference design values bundled per the lumber-spans tile. Jack studs from the end reaction over the NDS F_c-perp bearing. Allowable spans verified against IRC Table R602.7(1) by physics; the AHJ governs the adopted code. Free at codes.iccsafe.org and awc.org.",
  "helical-pile": "Citation: Torque correlation by name. Kt benchmarks from data/construction/helical-pile-kt.json (manufacturer-attributed). Engineer of record governs the design capacity and acceptance.",
  "helical-pile-torque": "Citation: torque correlation solved for the acceptance torque: torque = (allowable x FS) / Kt = ultimate / Kt, from ultimate = Kt x torque. Kt benchmarks from data/construction/helical-pile-kt.json (manufacturer-attributed). Engineer of record governs the design capacity and acceptance; a load test governs the true capacity.",
  "hip-valley-rafter": "Citation: Carpentry framing-square method by name. Common-rafter run multiplier sqrt(P² + 144)/12; hip / valley multiplier sqrt(P² + 288)/12 (diagonal-of-12-by-12 = 16.97).",
  "historical-pricing": "Citation: monthly history bundled from public BLS PPI / EIA / USDA NASS / FRED series. Each datapoint carries its source and series ID. Reference only; current quotes vary by region and supplier.",
  "home-office": "Citation: Per IRS Publication 587 (Business Use of Your Home) and Form 8829. Simplified method: $5/ft^2 up to 300 ft^2 ($1,500 cap, Rev. Proc. 2013-13). Actual method: (office ft^2 / home ft^2) x total home expenses. The tile reports the higher of the two. Free at irs.gov.",
  "hud-fmr": "Citation: HUD Office of Policy Development and Research, Fair Market Rents (FY2026, effective 2025-10-01). Free at huduser.gov / portal / datasets / fmr. The 40th-percentile rent of recent-mover units in the HUD-defined FMR Area; used for HCV (Section 8) program payment standards, ESG, HOME, and others.",
  "humidifier-capacity": "Citation: addition (lb/hr) = 60 x CFM x rho x (W_target - W_entering), with W from dry-bulb and RH at the altitude-corrected pressure; latent load = addition x 1061 BTU/lb. Per ASHRAE Fundamentals 2021 Ch. 1 (psychrometrics). AHJ and the manufacturer's published humidifier capacity govern actual delivery. Free at ashrae.org for the TOC.",
  "hydronic-buffer-tank": "Notice: A sizing aid, not the manufacturer's data; the equipment minimum-cycle data and the manufacturer govern. Citation: ASHRAE / Idronics (Caleffi) anti-short-cycle buffer-tank practice, by name. V = on_time x (source_min - zone_load) / (500 x delta_T). The worst case is at about zero load, when the full minimum output has nowhere to go but the tank; sizing at the design load undersizes it badly. The 500 factor is for water (adjust for glycol); existing distribution-piping water may already supply part of the volume.",
  "inspection-checklist": "Citation: Original plain-English checklists for rough-in and final inspections, organized by trade. AHJ governs.",
  "insulation-heat-loss": "Citation: Cylindrical conduction Q = (T_s - T_a) / (R_cond + R_outside) where R_cond = ln(r2/r1)/(2π k). Outside film coefficient h = h_conv(V) + h_rad(eps, T). k values from data/hvac/insulation-k-values.json (manufacturer-attributed).",
  "insulation-thickness": "Citation: Cylindrical conduction Q = 2*pi*k*L*dT / ln(r2/r1) iterated against an outside film coefficient (~1.65 BTU/hr/ft^2/F still air).",
  "iowa-rate-of-flow": "Notice: A fire-behavior teaching and size-up aid, not a water-supply design; incident command governs. Citation: Iowa rate-of-flow formula (Royer-Nelson / Iowa State fire behavior), by name. volume_ft3 = length x width x height; total_gal = volume_ft3 / 200 (one gallon controls ~200 ft^3 of compartment); rate_gpm = volume_ft3 / 100 (that water applied in the 30-second knockdown burst). This is a confined-compartment interior burst for a single open area, not the sustained flow the NFA and ISO methods size.",
  "irrigation-requirement": "Citation: Per FAO Irrigation and Drainage Paper 56 (Crop Evapotranspiration, Allen et al. 1998) and the USDA NRCS Irrigation Guide. ET_crop = Kc x ET0 x days; gross = max(0, ET_crop - rainfall) / efficiency; acre-ft = gross_in x acres / 12. Kc values from FAO 56 Table 12. Reference ET0 from your local CIMIS / Mesonet / NOAA station. Free at fao.org.",
  "irrigation-uniformity": "Citation: Christiansen 1942. CU = 100 * (1 - sum|x - mean| / (n * mean)). DU = 100 * mean(low quartile) / mean.",
  "irs-form-index": "Citation: IRS forms cited by number and published title only. No reproduction of form instructions. See irs.gov for the current edition of each form.",
  "iso-nff": "Citation: ISO Public Protection Classification (PPC) Schedule by name. NFF = Ci × Oi × (1 + X + P) where Ci = 18 × F × sqrt(A); rounded to the published 250 gpm increment and capped at 12 000 gpm. SOP-and-incident-command governs.",
  "keyseat-key-size": "Citation: ANSI B17.1 Keys and Keyseats (Machinery's Handbook): the standard key width from the shaft-diameter band; shaft keyseat depth = key height / 2; key shear = 2T/(D W L), bearing = 4T/(D H L). The key width is band-based, not D/4; a key longer than the hub adds no capacity. A design aid; the material allowables and fit class govern.",
  "knot-reference": "Citation: Original plain-English summary of common rigging and rescue knots with typical strength reductions cited from National Fire Academy / public training material.",
  "lab-safety-quickread": "Citation: GHS pictograms (UN GHS Rev. 9). OSHA Hazard Communication 29 CFR 1910.1200 by section number only. Original plain-English summaries.",
  "ladder-pipe-reach": "Citation: Aerial geometry plus stream-reach scaling. Stream projects forward at ~30 deg below horizontal (standard fireground assumption).",
  "level-loop-adjustment": "Citation: compass-rule (distance-weighted) level-loop adjustment, correction = -misclosure x cumulative-distance / total-distance, per the standard surveying references (Ghilani/Wolf), by name. The vertical analog of the horizontal compass rule; the project control and specs govern.",
  "lexile-band": "Citation: Common Core State Standards Appendix A (June 2010), Section III ('Quantitative Measures of Text Complexity'), and state-DOE bulletins implementing the CCSS stretch ranges (Smarter Balanced / PARCC consortium states). 'Lexile' is a registered trademark of MetaMetrics. Grade-band targets here are summarized from publicly published state-DOE guidance; the MetaMetrics text-measure tool itself is not bundled. Teacher governs final text selection.",
  "ligation-molar-ratio": "Citation: Standard molecular cloning - ligation insert:vector molar-ratio setup; insert_ng = ratio x (insert_length / vector_length) x vector_ng; vector_pmol = vector_ng / (vector_length x 650) x 1e3; insert_pmol = ratio x vector_pmol. The ratio is molar, not mass; 650 g/mol per bp is the dsDNA average (ssDNA and RNA differ); 3:1 is a starting point optimized empirically. The enzyme protocol and fragment ends govern.",
  "lighting-density": "Citation: per ASHRAE 90.1-2022 Table 9.5.1 (lighting power density by occupancy). AHJ governs adopted edition. Free at ashrae.org/technical-resources/standards-and-guidelines/read-only-versions-of-ashrae-standards.",
  "lighting-uniformity-ratio": "Citation: illuminance uniformity ratios (avg/min, max/min) and U0 = min/avg from a reading grid, per IES measurement/recommended practice. Common target ~3:1 max/min for offices. The IES RP for the space type governs.",
  "lightning-countdown": "Citation: Per NOAA / NWS lightning safety. The 30-30 rule is an NWS public guideline. Speed of sound ~ 1125 ft/s; 5 s ~ 1 mi. Free at weather.gov/safety/lightning.",
  "linear-interpolation": "Citation: First-principles linear interpolation - y = y1 + (x - x1)(y2 - y1)/(x2 - x1) - the straight-line read between two known table or chart points; public-domain. A linear estimate; a curved relationship between the points is approximated, so keep the two points close and confirm against the source table.",
  "linear-regression": "Citation: least-squares regression. slope = sum((x-xbar)(y-ybar)) / sum((x-xbar)^2); intercept = ybar - slope*xbar; R^2 = r^2; residual standard error = sqrt(RSS / (n-2)); slope t-test = slope / (RSE / sqrt(Sxx)) with the two-tailed p-value from the Student-t CDF. Per OpenIntro Statistics Ch. 8. Correlation is not causation; extrapolating beyond the data is unsupported. Free at openintro.org.",
  "livestock-dry-matter-intake": "Citation: Dry-matter intake per NRC Nutrient Requirements of Beef Cattle / Dairy Cattle: DMI = body weight x intake (% of BW on a dry-matter basis); as-fed = DMI / feed dry-matter fraction. Feed dry matter runs about 88% for dry hay and 30-40% for corn silage. A ration balancer and a nutritionist govern the actual diet.",
  "loan-amortization": "Citation: standard amortization formula P = (r * PV) / (1 - (1+r)^-n). First principles.",
  "loan-limits": "Citation: 2026 conforming loan limit per FHFA Conforming Loan Limit Values (annual, fhfa.gov). FHA single-family mortgage limit per HUD (entp.hud.gov / idapp / html / hicostlook.cfm). VA full-entitlement cap removed effective 2020-01-01 per the Blue Water Navy Vietnam Veterans Act. Unknown counties fall back to the baseline; verify against the FHFA / HUD lookup or with the lender.",
  "loto-steps": "Citation: 29 CFR 1910.147 by section number only. Original plain-English procedure summary. AHJ and employer LOTO procedure govern.",
  "lumber-spans": "Citation: per IRC 2021 Tables R502.5, R602.5 (joist / header / framing spans); AWC NDS-2018 governs by reference. M = w*L^2/8; sigma = Mc/I; delta = 5wL^4/(384*E*I). AHJ governs. Free at codes.iccsafe.org and awc.org.",
  "lv-dc-drop": "Citation: I*R round-trip drop. Application thresholds are widely-cited engineering benchmarks (LED 3 percent; ABYC marine 3/10 percent; RV 5 percent; audio 2 percent).",
  "macrs-depreciation": "Citation: IRS Publication 946 Tables A-1 (200%/150% DB, half-year). Table by class life.",
  "magnetic-declination": "Citation: Per NOAA / NCEI World Magnetic Model 2025 (WMM 2025), valid 2025-2030. Public domain. Free at ncei.noaa.gov/products/world-magnetic-model. Solar storms, local geological anomalies, and ferrous gear can shift the local field by several degrees beyond the model. The model is not a substitute for a recent compass calibration.",
  "manning-pipe-capacity": "Citation: Manning full-bore capacity V = (1.486/n) R^(2/3) S^(1/2), R = D/4, Q = V (pi/4) D^2, by name. Circular pipe flowing full; the roughness n is from the standard tables. The partial-flow depth is separate. A design aid; the engineer of record governs.",
  "manning-slope": "Citation: Manning's equation V = (1.486/n) * R^(2/3) * S^(1/2). Public engineering. Pipe roughness values from public engineering tables.",
  "manure-cover-savings": "Citation: manure storage covered-vs-open comparison (USDA-NRCS Conservation Practice 313 waste storage facility), by name. open = (manure + wastewater + bedding) x days + area x (net_precip + storm)/12 + area x freeboard/12; roof_saving = area x (net_precip + storm)/12; covered = open - roof_saving. The roof saving is the net precipitation and the 25-year, 24-hour storm the open facility must otherwise bank on its own surface; the freeboard is held the same in both cases. The saving is clean rainwater the operation also avoids hauling.",
  "manure-nutrient-application": "Citation: N-based manure application rate (USDA NRCS Code 590 Nutrient Management): available N per ton = total N x first-year availability, rate = crop N need / available N per ton, with the P2O5 and K2O delivered at that rate reported so phosphorus over-application is visible. A planning aid; a manure test, the soil test, and the nutrient-management plan govern.",
  "manure-storage-volume": "Notice: A planning aid, not the engineer of record; NRCS 313 and the engineer/planner govern. Citation: NRCS Conservation Practice Standard 313 / ASABE D384 manure production, by name. manure = (daily + wastewater + bedding) x storage_days; precip_storm = area x (net_precip + storm) / 12; freeboard = area x freeboard_in / 12; total = the sum. An uncovered facility must bank the net precipitation and the 25-year, 24-hour storm over the storage period; minimum storage is 120 days; freeboard is 6 in (vertical wall) or 12 in (other).",
  "markup-vs-margin": "Citation: Standard managerial-accounting pricing identity (cost-volume-profit), universal public formula; AICPA / introductory managerial-accounting texts, by name. Markup and margin diverge sharply (50% markup = 33.3% margin).",
  "masonry-count": "Citation: count = ceil(wall_area / face_area * 1.05). Face area uses (w + mortar) * (h + mortar).",
  "master-stream": "Citation: Reach scales as sqrt(P/P_typical) of the published base reach for each nozzle type.",
  "material-quantity": "Citation: Common-assembly coverage and waste factors are engineering rules of thumb. Verify against the specific manufacturer's published coverage.",
  "max-offer-70-rule": "Citation: Fix-and-flip 70% rule: maximum allowable offer = ARV x 70% - repair costs (minus any wholesale assignment fee). The 30% margin covers holding, financing, closing, and profit. A rule of thumb, not an appraisal; the ARV must come from real comparable sales and the repair estimate from a real scope. The investor's actual cost and profit targets govern.",
  "michaelis-menten": "Citation: Standard enzyme kinetics - the Michaelis-Menten equation; v = Vmax x [S] / (Km + [S]); percent_vmax = v / Vmax x 100. At [S] = Km the velocity is exactly half of Vmax. Km is the substrate concentration at half of Vmax (an affinity proxy, a low Km means high affinity, not a rate). The hyperbola approaches but never reaches Vmax. Assumes steady state with substrate far in excess of enzyme. The assay conditions govern.",
  "mileage-rollup": "Citation: IRS standard mileage rate (annual notice). Per-year rate bundled.",
  "moisture-dry-goal": "Citation: IICRC S500-2021 dry-standard concept by name (not reproduced): a material is dry when its moisture content matches similar unaffected material in the same structure. The protocol and a calibrated meter govern.",
  "molarity-from-stock": "Citation: Standard reagent preparation - stock molarity from assay and density, stock_M = 10 x purity_pct x density / MW; volume_to_draw = target_M x final_volume / stock_M. A concentrated liquid reagent is labeled by weight percent and density, not molarity, so both must be combined with the molecular weight (ignoring either is a 20-40% error). Always add concentrated acid to water, never the reverse. The reagent lot certificate of analysis and lab safety procedures govern.",
  "mold-conditions": "Citation: IICRC S520-2024 (Standard for Professional Mold Remediation, licensed) Condition framework, named by section; original plain-English summaries by the project author. The standard text is not reproduced.",
  "mold-remediation-level": "Citation: EPA 402-K-01-001 (Mold Remediation in Schools and Commercial Buildings, free at epa.gov/mold) area bands; NYC DOHMH Guidelines on Assessment and Remediation of Fungi levels; IICRC S520-2024 (licensed) by name. Scope guidance; the protocol of the assessor and remediator governs.",
  "molecular-weight": "Citation: IUPAC Standard Atomic Weights 2021. Bundled.",
  "motor-branch-from-nameplate": "Citation: Computed from nameplate. NEC 2023 §430.6(A)(1) requires using the table FLA values (430.247, 430.248, 430.250) for branch-circuit conductor and overcurrent sizing where motor nameplate is not the reference. Continuous-load 125 percent rule per §430.22. AHJ governs. Free at nfpa.org/freeaccess.",
  "motor-efficiency-upgrade-savings": "Citation: Premium-motor upgrade saving (first-principles): input kW = HP x 0.746 x load / efficiency; annual saving = (kW at old eff - kW at new eff) x run hours x rate. The saving scales with load, hours, and rate. Energy charge only; the utility tariff and rebates change the payback. A screening estimate, not a metered M&V.",
  "motor-fault-contribution": "Citation: first-cycle motor short-circuit contribution (IEEE C37.13 / IEEE 141): contribution = summed motor FLA / subtransient reactance (~4-6x FLA), total = utility fault + contribution. A first-cycle effect for the momentary and interrupting duty; grouped small motors often lumped at 4x FLA per IEEE C37.13. A design aid; a full short-circuit study governs.",
  "motor-feeder-multiple": "Citation: Feeder conductor and feeder overcurrent sizing for several motors on one feeder, per NEC 430.24 (conductor: 125% of the largest motor plus 100% of the rest) and NEC 430.62 (protection: the largest branch device plus the other motors' FLC), by name. Table FLC (not nameplate FLA) is used for this sizing per 430.6(A). The AHJ-adopted NEC edition governs. Free at nfpa.org/freeaccess.",
  "motor-fla": "Citation: Use motor nameplate FLA where available. Reference values per NEC 2023 Tables 430.247-430.250 and NEMA-aligned manufacturer technical bulletins. Free at nfpa.org/freeaccess.",
  "motor-locked-rotor-kva": "Citation: NEC 2023 Table 430.7(B) locked-rotor indicating code letters: the letter gives the locked-rotor kVA/hp band (upper end used here); locked_rotor_kva = hp x kVA/hp; LRA = kVA x 1000 / (sqrt(3) x V) three-phase. The code letter is not the design letter. A design aid; the nameplate and measured inrush govern.",
  "motor-max-hp-for-starting-current": "Citation: NEC 2023 Table 430.7(B) locked-rotor code letters solved for the horsepower: max hp = starting-current budget / (kVA/hp x 1000 / (sqrt(3) x V)) three-phase. The code letter is the starting-kVA letter, not the design letter. A design aid; the nameplate and measured inrush govern.",
  "motor-shaft-torque": "Citation: first-principles rotational-power identity T = 5252 x HP / RPM (5252 = 33,000 / 2 pi); supply HP to solve torque or torque to solve HP. The motor nameplate and the driven-load data govern the design torque.",
  "motor-vd-starting": "Citation: Ohm's-law voltage-drop method (first principles); motor locked-rotor current per NEC Article 430 code-letter tables (user-supplied, or 6x FLA estimate); contactor pickup/dropout commonly ~85% nominal per NEMA ICS 2, by name. The AHJ governs. Distinct from the steady-state voltage-drop tile. Free read-only at nfpa.org/freeaccess.",
  "mulch-topsoil-volume": "Citation: Bulk landscape material take-off (first-principles volume): cubic yards = area x depth / 324 (depth in inches), bags = ceil(yd^3 x 27 / bag size), tons = yd^3 x bulk density, truckloads = ceil(yd^3 / load). Bulk densities: mulch ~0.5, topsoil ~1.1, gravel ~1.4 ton/yd^3. A quantity aid; the supplier's bag/load size and product density govern.",
  "multi-leg-sling": "Citation: ASME B30.9 (slings) and standard rigging statics by name. Conservative tension = (load / 2 legs for >=3-leg rigid loads) / sin(angle from horizontal); the equal-share value is reference-only. The qualified rigger and the sling tag govern.",
  "nernst-equation": "Citation: Nernst equation E = E0 - (RT/nF) ln Q, R = 8.314 J/(mol*K), F = 96485 C/mol; at 25 C the slope is 0.05916/n V per decade of Q (Nernst; standard electrochemistry). Uses activities approximated by concentrations; excludes junction potential and overpotential. First principles.",
  "net-effective-rent": "Citation: net effective rent (straight-line concession spread; Appraisal Institute income approach / commercial-lease concession practice): paid = face x (term - free); NER = (paid - one-time credit) / term; discount = (1 - NER/face) x 100. A straight-line average, not a present-value effective rent. A comparison aid; the executed lease governs.",
  "neutral-current-3ph": "Citation: Phasor sum of three 120-degree-displaced currents (first principles). Neutral-as-current-carrying-conductor and harmonic guidance per NEC Article 310 and IEEE Std 519, by name; the AHJ-adopted edition governs. Result is RMS magnitude, not direction. Free read-only at nfpa.org/freeaccess.",
  "neutral-demand-220-61": "Citation: NEC 2023 220.61 (feeder and service neutral load). The neutral carries the maximum unbalanced load; 220.61(B) permits 70% on the portion over 200 A, and 220.61(C) prohibits any reduction for nonlinear-load portions. The AHJ governs. Free at nfpa.org/freeaccess.",
  "nfa-fireground-flow": "Notice: A size-up aid, not a water-supply design; incident command governs. Citation: National Fire Academy fireground fire-flow quick-calc (NFA; IFSTA), by name. base = (L x W / 3) x (percent/100) x floors; exposures add 0.25 x base each; total = base + exposures. Validated only for interior/offensive attack up to ~50% involvement and ~1,000 gpm - beyond that use the ISO / required-fire-flow method.",
  "nfpa-1142-water-supply": "Citation: Per NFPA 1142-2022 (Standard on Water Supplies for Suburban and Rural Firefighting) §5. AHJ governs final water-supply requirement. Free at nfpa.org/freeaccess.",
  "noise-dose": "Citation: Per OSHA 29 CFR 1910.95(b) Appendix A and Table G-16a. NIOSH 98-126 recommends a 3 dB exchange rate; this calculator implements the OSHA 5 dB rule because OSHA is the regulatory record. AHJ governs. Free at ecfr.gov and at cdc.gov/niosh.",
  "noncoincident-load": "Citation: NEC 2023 220.60 (noncoincident loads) - where two loads are unlikely to be in use at the same time, the larger is counted and the smaller omitted; the exception adds both where they operate simultaneously. The AHJ judges noncoincidence. Free at nfpa.org/freeaccess.",
  "npk-blend": "Citation: Per USDA NRCS Agronomy Technical Note ranges and the state Cooperative Extension Service published recommendations (state-keyed). Recommendation = max(0, crop demand - soil-test credit); the blend is solved from three straights (potash 0-0-60 for K, DAP 18-46-0 for P, urea 46-0-0 for the N balance). Your certified soil-test lab report and state Extension recommendation govern. Free at nrcs.usda.gov.",
  "npsh-a": "Citation: NPSHa = H_atm - H_vapor +/- H_static - H_friction (feet). Atmospheric head from elevation lapse; vapor pressure from public engineering table.",
  "occupant-load": "Citation: IBC 2021 §1004.5 and Table 1004.5 (occupant load = sum over spaces of ceil(area / occupant-load factor)); §1004.2 (round each space up to a whole person). Representative factors (ft^2/occ): assembly standing 5 net, chairs-only 7 net, tables-and-chairs 15 net, business 150 gross, mercantile 60 gross, classroom 20 net, commercial kitchen 200 gross, industrial 100 gross, storage 500 gross, residential 200 gross. The factor and its net-vs-gross basis come from the AHJ-adopted code edition and the actual use, not the tenant's label; a mezzanine or accessory use is its own line. A design aid, not a code-official determination.",
  "od600-cell-count": "Citation: Standard microbiology spectrophotometry; cells/mL = OD600 x factor x dilution. The OD-to-cells factor is strain- and instrument-specific and user-supplied (no universal constant). Linear range typically OD < ~0.8. Lab SOP governs.",
  "off-grid-battery": "Citation: Per IEEE 1013 (Sizing Lead-Acid Batteries for Stand-Alone PV Systems) and IEEE 1561 (PV / Hybrid Power Systems). Flooded lead-acid uses ~50% usable depth-of-discharge; lithium-iron-phosphate (LFP) uses ~80%. The manufacturer datasheet governs the chemistry-specific derate. Free at standards.ieee.org for IEEE 1013 bibliographic data.",
  "osha-recordkeeping": "Citation: 29 CFR 1904 by section number only. Original plain-English summary.",
  "outdoor-air-ventilation": "Citation: Per ASHRAE 62.1-2022 §6.2.2.1 (single-zone breathing-zone procedure). Rp and Ra values per Table 6-1 of the AHJ-adopted edition; the tile does not bundle the table. AHJ governs adopted edition. Free at ashrae.org for TOC.",
  "panel-rebalance": "Citation: per NEC 2023 §220 (load calculations) and §408.36 (panel rating). AHJ governs final panel sizing. Free at nfpa.org/freeaccess.",
  "parallel-conductor-derate": "Citation: Per NEC (NFPA 70) - paralleled conductors (Article 310, parallel-conductor provisions, 1/0 AWG and larger) and the more-than-three current-carrying-conductor adjustment factor (310.15(C)(1)). All parallel sets must be identical length, material, and termination. Conductor ampacities user-supplied from the adopted NEC ampacity table; the AHJ-adopted edition governs. Free read-only at nfpa.org/freeaccess.",
  "pcr-master-mix": "Citation: master-mix arithmetic. component_total = per_reaction * n_reactions * (1 + fudge_factor).",
  "pearson-correlation": "Citation: Pearson r = sum((x-xbar)(y-ybar)) / sqrt(sum(x-xbar)^2 * sum(y-ybar)^2). Significance via t = r * sqrt(n-2) / sqrt(1 - r^2) on n-2 degrees of freedom; two-tailed p from the Student-t CDF (incomplete beta, Numerical Recipes 6.4). Per OpenIntro Statistics Ch. 8. Correlation is not causation. Free at openintro.org.",
  "pearson-square-ration": "Citation: Pearson square method - standard land-grant animal-science ration formulation (USDA / university extension; Ensminger 'Feeds & Nutrition'), by name. The square is public arithmetic. Single nutrient only. Free at university extension sites.",
  "per-diem-interest": "Citation: CFPB Closing Disclosure prepaid-interest line (12 CFR 1026.38, Appendix H). Daily interest = loan * annual rate / day-count basis; prepaid interest covers the closing day through the last day of the month (the first regular payment, due the 1st of the following month, pays in arrears). Day-count convention varies by lender; Actual/365 is typical for owner-occupied conventional loans. Lender governs the actual figure.",
  "periodic-element": "Citation: IUPAC atomic numbers and element names (current IUPAC nomenclature). Pauling electronegativity values per Pauling, 'The Nature of the Chemical Bond' (3rd ed., 1960) and the modern IUPAC + Allred-Rochow consolidations. Electron configurations per NIST Atomic Spectra Database. Common oxidation states per the published Greenwood + Earnshaw, 'Chemistry of the Elements' (2nd ed., 1997) and Cotton + Wilkinson references.",
  "phase-balance": "Citation: Imbalance percent = (max - min) / average * 100. Greedy swap rebalances by moving the smallest fitting circuit from heaviest to lightest phase.",
  "pipe-expansion": "Citation: Linear thermal expansion dL = alpha * L * dT. Coefficients (per F) from NIST and manufacturer technical bulletins.",
  "pipe-expansion-loop": "Citation: dL = alpha × L × ΔT (per-material alpha). Guided-cantilever expansion-loop leg L_loop = sqrt(3 × E × D × dL / S_a) by name.",
  "pipe-heat-loss-radial": "Citation: Fourier conduction through a cylindrical shell (public heat-transfer formula); insulation k-values per ASHRAE Fundamentals / ASTM C335, by name (user-supplied). Distinct from the flat-wall insulation tiles - this is the radial log-mean form. k is at the mean insulation temperature.",
  "pipe-partial-flow-depth": "Citation: Manning's equation applied to the circular-segment geometry (A = (D^2/8)(theta - sin theta), P = D theta/2, y = (D/2)(1 - cos(theta/2))) and solved for the partial-flow normal depth by bisection, the standard gravity-sewer partial-flow relation as compiled in ASCE/WEF MOP FD-5 and Chow, by name. The maximum-discharge depth d/D = 0.938 and maximum-velocity depth d/D = 0.813 are derived from these equations, not tabulated. Roughness n from the standard tables; self-cleansing taken as 2 ft/s. Constant n with depth (Camp's variable-n curves are separate). A design aid; the engineer of record and the local sewer code govern.",
  "pipe-sizing": "Citation: WSFU per IPC 2021 Table 604.3 and DFU per Table 709.1; Hunter's Curve (1940; NBS BMS65) public-domain methodology converts water-supply fixture units to gpm. AHJ governs. Free at codes.iccsafe.org.",
  "pipe-template-wrap": "Citation: The pipefitter's wraparound (ordinate) method for marking an angled pipe cut, y = (OD/2)*tan(alpha)*(1 - cos(phi)), as taught in NCCER Pipefitting and the standard layout references, by name; first-principles geometry. A layout aid - the bevel and fit-up govern the finished joint.",
  "pipe-volume": "Citation: V = (pi/4) * d^2 * L. 1 US gallon = 231 in^3.",
  "pitot-traverse-average": "Citation: Pitot-tube traverse airflow averaged the correct way (ASHRAE Fundamentals / AABC / NEBB field practice, by name): convert each equal-area point's velocity pressure to a velocity V = 4005 x sqrt(VP) for standard air (0.075 lb/ft^3, sea level), average the velocities, then CFM = average velocity x duct area. Averaging the velocity pressures first reads high because the square root is concave. Apply a density correction at altitude or high temperature. A field measurement, not a substitute for a calibrated flow station.",
  "pitot-traverse-cfm": "Citation: Pitot-tube traverse airflow (ASHRAE Fundamentals / AABC-NEBB field practice): velocity V = 4005 x sqrt(VP) for standard air (0.075 lb/ft^3, sea level) from a single traverse-average velocity pressure, then CFM = V x duct area. This takes one pre-averaged VP; the more exact method converts each point's VP to a velocity and averages the velocities (the pitot-traverse-average tile), which reads slightly lower because the square root is concave. Apply a density correction at altitude or high temperature. A field measurement, not a substitute for a calibrated flow station.",
  "pivot-application-rate": "Citation: center-pivot outer-span application rate (USDA-NRCS center-pivot design; university extension), by name. speed = 2 x pi x pivot_length / (revolution_hr x 60); wetting = wetted_band / speed; app_rate = pass_depth x 2 x pi x pivot_length / (revolution_hr x wetted_band). This is the average rate over the wetted band at the outer span (the true peak runs about 6% higher); the outer end governs because it moves fastest. Runoff is avoided only by the short wetting time and surface storage, so a slope or a tight soil runs off when the rate exceeds the intake.",
  "pivot-timer-depth": "Citation: center-pivot percent-timer to depth (USDA-NRCS center-pivot design; university extension), by name. revolution = revolution_100_hr x 100 / timer_pct; depth = system_flow x revolution / (452.6 x area); pass_days = revolution / 24. The timer sets the outer-tower speed, so the depth is inversely proportional to the setting - halving the timer doubles the depth. The full-speed revolution time is the machine's rated maximum-speed pass.",
  "plate-cost": "Citation: Public restaurant operations practice. Suggested menu price = plate cost / target food-cost %.",
  "plywood-span": "Citation: APA span-rating tables (data/construction/apa-span-ratings.json) cited by APA name only. AHJ governs.",
  "pmi-cancellation-date": "Citation: Per the Homeowners Protection Act of 1998 (12 USC 4901-4910) - automatic termination at 78% and borrower-requested cancellation at 80% of original value, with the amortization-midpoint requirement, by name; applies to borrower-paid PMI on conventional loans, not FHA MIP. CFPB consumer guidance free at consumerfinance.gov; uscode.house.gov for the statute. Estimate; the servicer governs.",
  "point-load-bearing": "Citation: Per the National Design Specification (NDS) for Wood Construction - compression perpendicular to grain and the bearing-area factor Cb, by name; Fc-perp values user-supplied by species/grade. The IBC-adopted NDS edition governs. AWC publishes the NDS free read-only at awc.org.",
  "pool-bonding-680-26": "Citation: NEC 2023 680.26 (equipotential bonding) - the 680.26(B) bonded-component list, the 3 ft perimeter, the listed water bond (680.26(C)), and the #8 AWG solid copper minimum. The grid is equipotential; the AHJ governs the inspection. Free at nfpa.org/freeaccess.",
  "press-brake-max-thickness": "Citation: Press-brake air-bend tonnage formula (the 575 mild-steel constant) solved for the thickness: T = sqrt(tons x V / (575 x (UTS/60) x L)), as published in press-brake tonnage charts / Machinery's Handbook, by name; empirical method. Air bending only; bottoming and coining run higher and the die maker's chart governs.",
  "press-brake-tonnage": "Citation: Press-brake air-bend tonnage formula (the 575 mild-steel constant) as published in press-brake tonnage charts / Machinery's Handbook, by name; empirical method. The user supplies the geometry and may override the strength; bottoming and coining run higher, and the die maker's chart governs the final setup.",
  "press-fit-interference-for-force": "Citation: Lame interference-fit relations (Machinery's Handbook 'Forces and Fits'; Lame thick-cylinder equations, same-material solid shaft) solved for the interference: i = holding x 2 Do^2 / (E x (Do^2 - D^2) x pi x L x mu); contact pressure and hub bore stress reported at that interference. A design aid; the materials, surface finish, and assembly method govern.",
  "press-fit-pressure": "Citation: Lame interference-fit relations (Machinery's Handbook 'Forces and Fits'; Lame thick-cylinder equations, same-material solid shaft): p = (E x interference / D) x (Do^2 - D^2)/(2 Do^2); holding force = p x pi x D x length x friction; hub bore stress = p x (Do^2 + D^2)/(Do^2 - D^2). A design aid; the materials, surface finish, and assembly method govern.",
  "pressure-conversion": "Citation: NIST SP 811 unit factors. 1 psi = 6894.757 Pa; 1 atm = 101325 Pa; 1 in w.c. = 248.84 Pa.",
  "prevailing-wage-fringe": "Citation: Prevailing-wage fringe (Davis-Bacon / state determination): package = base wage + fringe; paying the fringe as cash makes it taxable wages, funding it through a bona-fide plan does not, saving fringe x the wage-based burden per hour. A budgeting aid; the wage determination and the plan's bona-fide status govern.",
  "product-pull-down-load": "Citation: Product pull-down load (ASHRAE Refrigeration): above freezing Q = m cp deltaT; for a freezer Q = sensible-to-freezing + m x latent heat of fusion + sensible-of-frozen; rate = Q / pull-down hours. A sizing aid; the product property tables govern.",
  "product-pull-down-time": "Citation: Product pull-down time (ASHRAE Refrigeration): hours = Q / capacity, with Q = m cp deltaT above freezing, or sensible-to-freezing + m x latent heat of fusion + sensible-of-frozen for a freezer. A sizing aid; the product property tables govern.",
  "psychrometric": "Citation: August-Roche-Magnus saturation vapor pressure approximation; standard psychrometric definitions.",
  "pump-operating-point": "Citation: System curve H_sys = H_static + k Q². Operating point at the intersection with the bundled pump curve. Curves cited per manufacturer name in data/plumbing/pump-curves.json.",
  "pump-sizing": "Citation: Hydraulic horsepower HP_h = (Q * H * SG) / 3960; shaft hp = HP_h / efficiency.",
  "pump-tdh": "Citation: TDH = static head + suction friction + discharge friction + fittings friction. Friction is Hazen-Williams (Crane Technical Paper No. 410). Enter the pipe internal diameter, C factor (150 PVC, 130 new steel, 100 old steel), and fittings equivalent length from TP-410. The manufacturer pump curve governs the operating point. Free at flowoffluids.com for Crane TP-410 excerpts.",
  "pv-performance-ratio": "Citation: PV performance ratio as the product of (1 - loss) over the NREL/PVWatts-style derate stack (soiling, temperature, wiring, inverter, mismatch, shading, availability, nameplate, LID, connections), by name. A screening stack, not a metered performance ratio. A design aid.",
  "quadratic-mean-diameter": "Citation: USDA Forest Service forest-mensuration practice (quadratic mean diameter), by name. QMD = sqrt( sum(count x diameter^2) / sum(count) ); tally token is a diameter (\"12\") or a class (\"12:40\" or \"12 x 40\"), separated by commas or new lines. QMD is the diameter of the tree of average basal area, always at or above the arithmetic mean - it is the number reineke-sdi requires. The total basal area is 0.005454 x sum(count x diameter^2) ft^2 for the tallied trees, not a per-acre expansion.",
  "raceway-expansion-fitting": "Citation: PVC raceway thermal expansion and expansion-fitting sizing - dL = alpha * L * dT with the NEC Table 352.44 coefficient (3.38e-5 in/in/F), an expansion fitting required where the change is 0.25 in or greater in a straight run - per NEC Article 352.44 and Table 352.44 (rigid PVC conduit), by name; first-principles linear expansion. Set the fitting piston per the manufacturer's temperature chart at the install temperature. The AHJ-adopted NEC edition governs.",
  "rainwater-catchment-area": "Citation: public engineering form solved for area: area = target_gal / (annual_in * 0.6233 * efficiency), from gallons = area * rainfall * 0.6233 * efficiency. Default efficiency 0.62 for sloped roofs. A planning estimate; local rainfall, storage, and demand govern.",
  "rainwater-yield": "Citation: Public engineering form gallons = area * rainfall * 0.6233 * efficiency. Default efficiency 0.62 for sloped roofs.",
  "readability": "Citation: Flesch-Kincaid Grade Level per Kincaid, Fishburne, Rogers, and Chissom, 'Derivation of New Readability Formulas,' Naval Technical Training Command Research Branch Report 8-75 (1975), public-domain. Flesch Reading Ease per Flesch, 'A New Readability Yardstick,' Journal of Applied Psychology 32:3 (1948). Syllable counter is a vowel-cluster heuristic with silent-e and -le adjustments; differs from a dictionary syllable count by roughly 5 percent on edge cases (proper nouns, technical jargon).",
  "rebar-schedule": "Citation: Unit weights from data/construction/rebar-unit-weights.json (ACI/CRSI by name only). Bend allowance 90°/135° = 6 db, 180° = 4 db, stirrup = 14 db, hook = 6 db. Engineer of record governs the schedule.",
  "recipe-scale": "Notice: Bakers' percentages and yeast / leavening do not scale linearly. Verify critical ratios. Citation: USDA FoodData Central reference weights, public domain.",
  "recirc-loop-sizing": "Citation: Per ASPE Data Book Vol. 4 (Plumbing Engineering Design Handbook) Chapter 6 simplified per-foot heat-loss method. Friction head via Hazen-Williams (C=140 for copper). Annual cost = standing heat loss x runtime / heater efficiency / (100,000 BTU/therm gas or 3,412 BTU/kWh electric) x fuel price. ASHRAE 90.1-2022 §7.4.4 governs recirculation control requirements where adopted. AHJ governs. Free at aspe.org for TOC.",
  "recirc-pump-head": "Citation: Hazen-Williams head loss over the supply loop plus an equivalent-length allowance for fittings. Public engineering practice.",
  "refrigerant-charge": "Citation: Manufacturer line-set charge tables (oz per foot per refrigerant per diameter). Attribute manufacturer per entry.",
  "refrigerant-line-size": "Citation: Per the ASHRAE Refrigeration Handbook line-sizing and oil-return guidance, by name (the velocity relation solved for the line ID). Refrigerant specific volume at the line condition is user-supplied. Estimate; manufacturer line-sizing tables govern.",
  "refrigerant-mass-flow": "Citation: refrigerant mass flow m_dot = Q / (h1 - h4), the refrigeration effect RE = h1 - h4 from the P-h diagram, 1 ton = 200 Btu/min, and h4 = hf at the condenser (isenthalpic throttling), by name. Enter the enthalpies; steady flow. An engineering aid; the refrigerant property data govern.",
  "refrigerant-pt": "Citation: Manufacturer-published P-T tables for common refrigerants. Each refrigerant attributes its publishing manufacturer.",
  "refrigerant-velocity": "Citation: Per the ASHRAE Refrigeration Handbook line-sizing and oil-return guidance, by name. Refrigerant specific volume at the line condition is user-supplied. Estimate; manufacturer line-sizing tables govern.",
  "relay-pump-distance": "Notice: A planning aid, not incident command; the SOP and the pump's real capability govern. Citation: IFSTA Pumping Apparatus Driver/Operator relay pumping maximum distance, by name. budget = max_discharge - intake_residual - 0.434 x elevation; FL_per_100 = C x (Q/100)^2; max_distance = budget / FL_per_100 x 100. The next pumper needs a 20 psi intake residual or it cavitates, so the usable pressure is the max discharge minus 20 minus the lift; distance falls with the square of flow.",
  "rent-vs-buy": "Citation: New York Times rent-vs-buy methodology (first-principles DCF). Each path is a present value of out-of-pocket cost discounted at the investment-return rate. PV_buy = down payment + PV(P&I + tax + insurance + HOA + maintenance) − PV(net sale proceeds); PV_rent = PV(inflating rent). Lower PV wins. Tax treatment (mortgage-interest deduction, Section 121 capital-gains exclusion) is out of scope and varies; consult a CPA. Estimate only; lender and market govern actual figures.",
  "rental-total-return": "Citation: Rental total return (real-estate investing practice): total = cash flow + principal paydown + appreciation + depreciation tax savings, each as a percent of cash invested. Cash-on-cash alone ignores equity buildup and the tax shield, understating the return. Appreciation is a projection. A screening aid; the actual results govern.",
  "rental-worksheet": "Citation: IRS Schedule E (Form 1040), Supplemental Income and Loss, Part I (Income or Loss From Rental Real Estate). Expense categories mirror Schedule E lines 5-19. NOI excludes depreciation (a non-cash, separately-tracked line). Passive-loss rules (26 USC §469) govern whether a taxable rental loss reduces other income. The gross-rent multiplier (GRM = property value / annual gross rent) and the value it implies at a market GRM are the income-approach quick-screen per the Appraisal Institute, The Appraisal of Real Estate. CPA / appraiser governs.",
  "reorder-point": "Citation: reorder point and safety stock (service-level inventory control): z = inverse_normal(service_level/100); safety_stock = z x demand_sd x sqrt(lead_time); reorder_point = avg_daily_demand x lead_time + safety_stock. Safety stock scales with sqrt(lead time) and the z-score, so the last few points of service cost a disproportionate buffer. A planning aid; the demand pattern and supplier reliability govern.",
  "required-face-rent": "Citation: required face rent (inverse of the straight-line net-effective-rent spread; Appraisal Institute income approach / commercial-lease concession practice): face = (target_NER x term + one-time credit) / (term - free); discount = (1 - NER/face) x 100. A straight-line average, not a present-value effective rent. A pricing aid; the executed lease governs.",
  "required-fire-flow": "Citation: per IFC 2021 Table B105.1 (ISO needed-fire-flow method). NFF = C * O * X * P; C = 18 * F * sqrt(A). AHJ governs. Free at codes.iccsafe.org.",
  "residential-framing": "Citation: per IRC 2021 Tables R502.5 (joist spans), R602.5 (stud schedules), R802.5.1 (rafter spans). AHJ governs. Free at codes.iccsafe.org. Board-feet conventions per WWPA standard grading rules.",
  "reverse-lay-friction": "Citation: NFA CQ^2L extended to tandem-pump operation. Per-pump friction (parallel section) scales as (1/n_pumps)^2.",
  "roller-chain-length": "Citation: ANSI B29.1 roller-chain length: L = 2(C/p) + (N1+N2)/2 + ((N2-N1)/(2 pi))^2/(C/p) pitches, rounded UP to an even count (an odd count needs a weaker offset link), then the center distance recomputed C = (p/4)[A + sqrt(A^2 - 8((N2-N1)/(2 pi))^2)]. A design aid; the sprocket selection and take-up govern.",
  "rolling-offset": "Citation: First-principles rolling-offset trigonometry used in pipe fitting and conduit work: true offset = sqrt(rise^2 + roll^2) by Pythagoras, travel = true offset times the cosecant of the fitting angle, run advance = true offset / tangent. Public method as taught in NCCER pipefitting and the standard fitter's references; fitting make-up/take-out is product-specific and user-supplied; pairs with conduit-offset.",
  "roof-pitch": "Citation: Pitch geometry. Rise/run = tan(angle); 6/12 corresponds to roughly 26.6 degrees and 50 percent.",
  "rope-ma": "Notice: Departmental SOPs and incident command govern all rope-rescue operations. Citation: NFA / NFPA training literature by name only.",
  "round-to-rect-duct": "Citation: The ASHRAE equal-friction circular equivalent of a rectangular duct, D_e = 1.30*(a*b)^0.625/(a+b)^0.250, per ASHRAE Fundamentals (duct design) and SMACNA, by name; first-principles. An equal-friction equivalence, not an equal-velocity one. The fabrication drawing governs.",
  "sag-vertical-curve": "Citation: AASHTO sag vertical-curve minimums per A Policy on Geometric Design of Highways and Streets (the Green Book), headlight sight-distance criterion: L = A S^2 / (400 + 3.5 S) for S <= L and L = 2 S - (400 + 3.5 S)/A for S > L, where 400 and 3.5 embed the 2.0 ft headlight height and 1-degree beam divergence; K = L/A. This is the headlight-SSD control (the governing sag stopping criterion); the comfort criterion L = A V^2/46.5 and drainage K <= 167 are separate checks. A design aid, not a substitute for a licensed civil engineer's design.",
  "sag-vertical-curve-comfort": "Citation: AASHTO comfort and drainage sag vertical-curve controls per A Policy on Geometric Design of Highways and Streets (the Green Book): the comfort criterion L = A V^2 / 46.5 (A in %, V in mph, L in ft) limits the vertical acceleration to about 1 ft/s^2, giving K = L/A = V^2/46.5; the drainage maximum K <= 167 (a 0.30% minimum grade within 50 ft of the low point) caps the length at 167 A on curbed sections. These bracket the acceptable length; headlight stopping sight distance is the separate governing control (the sag-vertical-curve tile). A design aid, not a substitute for a licensed civil engineer's design.",
  "sales-tax": "Citation: bundled state revenue department published average combined rates. Verify locally for accuracy.",
  "sales-tax-nexus": "Citation: per-state department of revenue published nexus guidance. Verified-on date stamped per entry.",
  "sanitary-dfu": "Citation: total DFU = sum(fixture count x DFU value); minimum pipe size from the max-DFU table. Per IPC 2021 §710 with DFU values per IPC Table 709.1 and capacities per Tables 710.1(1) and 710.1(2). AHJ governs the adopted code. Free at codes.iccsafe.org.",
  "scba-cylinder-time": "Citation: Per NFPA 1981-2019 (Open-Circuit SCBA for Emergency Services) and NIOSH 42 CFR 84. Manufacturer cylinder rating governs absolute scf. Field consumption varies with work rate; this is a planning estimate. Free at nfpa.org/freeaccess and ecfr.gov.",
  "sccr-combination": "Citation: UL 508A Supplement SB industrial-control-panel SCCR (weakest-link method); NEC 409.110 / 110.10. The panel SCCR = min(component SCCRs, feeder OCPD interrupting rating), and it must meet or exceed the available fault current. One low-rated component caps the whole panel; a current-limiting fuse ahead of a weak component can raise the combination through its let-through. UL 508A and the AHJ govern.",
  "scientific-notation": "Citation: Scientific notation = m * 10^n where 1 <= |m| < 10 (or m = 0). Significant-figure count is derived from the input string: leading zeros are not significant; embedded zeros and trailing zeros after a decimal point are significant.",
  "search-probability": "Citation: Standard SAR search theory (Koopman detection theory) as used in the U.S. National SAR Supplement and NASAR / FEMA search-planning doctrine, by name; POD/POA/POS definitions are public. Method cited, not reproduced. POS is always <= POA.",
  "search-track-spacing": "Notice: The incident commander and search plan govern all SAR operations. Citation: NSARC / USCG search theory (exponential detection model) by name. coverage = W / S; POD = 1 - e^(-coverage); spacing = W / (-ln(1 - target_POD)). The sweep width must be corrected for weather, fatigue, terrain, and speed. The random-search model is conservative; parallel-track sweeps reach higher POD at the same coverage.",
  "searcher-hours": "Notice: The incident commander and search plan govern all SAR operations; a planning aid, not a promise of coverage. Citation: NSARC / USCG search-planning practice (effort = area over spacing over speed), by name. track_ft = 43,560 x area_acres / spacing_ft; searcher_hours = track_ft / (speed_mph x 5,280); team_clock_hr = searcher_hours / searchers. Raw grid-walking effort only - briefing, travel, rest, and terrain detours add on top.",
  "section-121-exclusion": "Citation: IRC §121 (Exclusion of Gain from Sale of Principal Residence), single cap $250,000 / joint cap $500,000. Two-of-five-year ownership and use test per §121(a). Partial exclusion per §121(c) for unforeseen circumstances. Non-qualified-use reduction per §121(b)(5) for periods after 2008. CPA and the IRS Form 8949 / Schedule D instructions govern the actual return; this tile is an estimate.",
  "section-179": "Citation: IRC 179 cap and phase-out from IRS annual revenue procedures; bonus depreciation per IRC 168(k). Per-year parameters bundled.",
  "seismic-overturning-moment": "Citation: ASCE 7-22 12.8.5 (Overturning): the structure resists the overturning caused by the 12.8.3 story forces Fx = Cvx V, Cvx = wx hx^k / Sum(wi hi^k), with k = 1 for T at or below 0.5 s, k = 2 at or above 2.5 s, linear between. The base overturning moment M0 = Sum(Fi hi); the moment about level x is Sum over the forces above x of Fi (hi - hx). 12.13.4 permits a 25% reduction of the ELF overturning moment at the soil-foundation interface, reported as the reduced foundation moment. Weights are the effective seismic weights per 12.7.2; V and T come from seismic-base-shear and the distribution. The resisting dead load, the foundation stability ratio, and the shear-wall hold-down design are separate checks. A design aid, not a lateral-analysis substitute; the engineer of record governs.",
  "seismic-vertical-distribution": "Citation: ASCE 7-22 12.8.3 vertical distribution, Fx = Cvx x V (Eq. 12.8-11) with Cvx = wx hx^k / Sum(wi hi^k) (Eq. 12.8-12), and 12.8.4 story shear Vx = Sum Fi at and above the level (Eq. 12.8-13). The exponent k = 1 for T at or below 0.5 s, k = 2 at or above 2.5 s, linear interpolation between (the standard also permits k = 2 outright in that band). Weights are the effective seismic weights per 12.7.2; heights are from the base. Assumes the ELF procedure is permitted for the structure (12.6 system and irregularity limits). Feeds the story shear that seismic-story-drift and seismic-pdelta-stability consume. A design aid, not a lateral-analysis substitute; the engineer of record governs.",
  "seller-net-sheet": "Citation: Per the TILA-RESPA Integrated Disclosure / Closing Disclosure (12 CFR 1026.38) and RESPA (12 CFR 1024), by name; the transfer-tax rate is state/local and user-supplied. Distinct from the buyer-side closing-costs tile. Estimate; the settlement statement and closing agent govern. Free at consumerfinance.gov and ecfr.gov.",
  "septic-drainfield": "Citation: Required absorption area = design flow / application rate. State and county codes set the application rate. Enter the value from your local code; the tool does not bundle a per-state shard. AHJ governs.",
  "septic-drainfield-capacity": "Citation: Design flow a field supports = trench length x trench width x application rate (the inverse of the required-area sizing); bedrooms = flow / the code's per-bedroom design flow (EPA baseline 150 gpd/bedroom). State and county codes set the application rate and the per-bedroom flow. AHJ governs.",
  "service-load-optional": "Citation: Per NEC 2023 220.82 (optional dwelling load calculation): general load demand = first 10 kVA at 100% + remainder at 40%; 220.82(C) adds the larger of heating vs cooling at 100%. Compared against the standard 220.42 method; size to the larger. AHJ governs the adopted edition. Free at nfpa.org/freeaccess for the NEC table of contents.",
  "service-load-standard": "Citation: NEC 2023 Article 220 Standard Method (general lighting 3000 VA at 100% / next 117000 VA at 35% / remainder at 25%; 220.53 fixed-appliance 75% if 4+; 220.54 dryer 5000 W min; 220.55 range simplified). AHJ governs.",
  "shadow-length": "Citation: sun shadow-length geometry (first-principles trigonometry): shadow = object height / tan(sun altitude); shadow-to-height ratio = cot(altitude). At 45 degrees the shadow equals the height; a low sun throws a long shadow. Use the winter-design sun elevation for the worst-case shade. Level ground and a vertical object assumed; the sun path and terrain govern.",
  "short-circuit-pp": "Citation: Bussmann point-to-point method by name. C-values from data/electrical/conductor-c-values.json.",
  "shr-latent": "Citation: Per ASHRAE Fundamentals 2021 Chapter 1 (psychrometrics) and Chapter 18 (nonresidential cooling and heating load calculations). Sea-level coefficients (1.08 sensible, 4840 latent) per ASHRAE Handbook; altitude correction via the standard atmosphere density ratio. Field measurement is the verdict; the rated total capacity is one input among several. Free at ashrae.org for TOC; full handbook is licensed.",
  "significant-figures": "Citation: Significant-figure conventions per NIST SP 811 (Guide for the Use of the International System of Units) §7. Leading zeros not significant; trailing zeros after a decimal point ARE significant; trailing zeros in an integer without a decimal point are ambiguous and not counted here (use scientific notation for explicit precision).",
  "sling-angle": "Notice: Departmental SOPs and incident command govern all rigging and lifting operations. Citation: ASME B30.9 by section number only. L = W / (n * sin(theta/2)).",
  "slope": "Citation: Geometric slope. 1/4 inch per foot equals approximately 2.08 percent or 1.19 degrees.",
  "slope-stake-cut-fill": "Citation: Slope-stake cut/fill and catch-point geometry per FM 5-233 Construction Surveying and FHWA construction-survey guidance, planar approximation. The grading plan and surveyor of record govern.",
  "sluice-gate-flow": "Citation: free-flow sluice (underflow) gate discharge Q = Cd b a sqrt(2 g y1), with Cd = Cc / sqrt(1 + Cc a / y1) and the contraction coefficient Cc ~ 0.61 for a sharp-edged vertical gate (first-principles open-channel hydraulics, Henderson Open Channel Flow / USBR Water Measurement Manual). g = 32.2 ft/s^2; a = gate opening, b = width, y1 = upstream depth above the floor. Free-flow only: the tailwater must not drown the contracted jet. Free at usbr.gov/tsc/techreferences/mands/wmm.",
  "smoke-ejector-cfm": "Notice: Departmental SOPs and incident command govern all ventilation operations. Citation: per NFPA 1500 §8.5 and the IFSTA Essentials of Fire Fighting ventilation chapter. CFM = volume * ACH / 60; fans = ceil(CFM / per-fan rating). Free at usfa.fema.gov.",
  "smoke-reading": "Citation: Original plain-English summaries of established fire-science training on smoke volume, velocity, density, and color interpretation.",
  "solar-altitude-angle": "Citation: solar altitude angle (NOAA/ASHRAE solar geometry): sin(altitude) = sin(lat) sin(dec) + cos(lat) cos(dec) cos(H), with the declination from Cooper's equation dec = 23.45 sin(360 (284 + n)/365) and the hour angle H = 15 (hours from solar noon); at solar noon altitude = 90 - |lat - dec|. True solar time and a flat horizon assumed; refraction and the equation of time are separate. A site-planning geometry; the actual sun path governs.",
  "soot-cleaning-takeoff": "Citation: Dry-sponge soot cleaning takeoff and the 300 ft^2/gal primer coverage (ANSI/IICRC S700 fire and smoke restoration), by name. The RESIDUE TYPE governs the method - dry sponging is for dry smoke; protein, wet, and fuel-oil residues need wet cleaning instead. A quantity screen, not a cleaning protocol.",
  "sous-vide-pasteurization": "Citation: Per FDA Food Code Annex 6 Table A 6.5-log Salmonella reduction values. Come-up time from the slab-form thermal-diffusion approximation (Heisler chart at centerline, Fo ~ 0.4). Bundled food-thermal-diffusivity values per public engineering references (Baldwin Practical Guide to Sous Vide Cooking). Local food-safety authority and a qualified processing authority govern commercial-kitchen use. Free at fda.gov/food/retail-food-protection/fda-food-code.",
  "speaker-70v-line": "Citation: Constant-voltage (70 V / 100 V) distributed-audio line design - tap-wattage budget, reflected line impedance Z = V^2/P, and run line-loss - per the standard 70 V distributed-system practice and NEC Article 640 / 725 (Class 2/3 audio) wiring, by name; first-principles Ohm's law. Distinct from the low-impedance speaker-impedance (Group N) tile. The amplifier spec governs.",
  "spiral-curve": "Citation: spiral (transition/clothoid) curve geometry per AASHTO A Policy on Geometric Design of Highways and Streets (the Green Book) and Ghilani & Wolf, Elementary Surveying: theta_s = Ls/(2R), throw p = Ls^2/(24R), k = Ls/2 - Ls^3/(240 R^2), Ts = (R+p) tan(delta/2) + k, Es = (R+p)/cos(delta/2) - R, SC deflection = theta_s/3. Symmetric spirals, series approximation. The design of record and engineer of record govern.",
  "spl-atmospheric": "Citation: Inverse-square law for far-field distance attenuation. Atmospheric absorption per ANSI S1.26-2014 (R2019) - per-octave-band alpha (dB/m) at the operator-supplied temperature / RH / pressure, applied multiplicatively over distance. For closed venues, room acoustics dominate over inverse-square. AHJ governs final coverage. Free at ansi.org for TOC.",
  "spore-io-ratio": "Citation: Indoor/outdoor spore ratio and the marker-genera principle (ANSI/IICRC S520), by name. An independent environmental professional interprets clearance; a ratio at or under 1 alone does not clear a project. A screen, not a certificate.",
  "sprayer-calibration": "Citation: Per USDA Cooperative Extension Service public 1/128-acre calibration method. Pesticide label rates govern application; pesticide-applicator license governs use. Free at extension.org and at land-grant university extension offices.",
  "sprinkler-density": "Citation: per NFPA 13-2022 Table 12.1 (hazard density). total_gpm = area * density (gpm/ft^2). AHJ governs. Free at nfpa.org/freeaccess.",
  "sprinkler-k-factor": "Citation: Per the NFPA 13 sprinkler discharge relation Q = K x sqrt(P) (Q gpm, P psi, K nominal nameplate K-factor). Complements the sprinkler-density tile. NFPA 13 governs the design; free read-only at nfpa.org/freeaccess.",
  "sprocket-pitch-diameter": "Citation: ANSI B29.1 sprocket pitch diameter PD = p / sin(180 deg / N) and maximum outside diameter OD = p (0.6 + cot(180 deg / N)), for chain pitch p and tooth count N. A design aid; the manufacturer's tooth form and hub govern.",
  "ssd-design-speed": "Citation: AASHTO Green Book stopping sight distance solved for speed: v is the positive root of v^2/(30(f+g)) + 1.47 t v - SSD = 0. A design aid; the AASHTO Green Book and the state DOT govern posted and design speeds. Free at transportation.org for TOC.",
  "stair-stringer": "Citation: stringer_ft = sqrt(rise^2 + run^2). Board-foot estimate uses a 2x12 stringer (1.5 in x 11.25 in actual).",
  "stair-stringer-layout": "Citation: First-principles geometry. Code-check pass/fail uses the user-entered local-code rise max and tread min; the tool does not bundle code values. AHJ governs.",
  "standards-based-grade": "Citation: Marzano + Heflebower, 'A Handbook for Developing and Using Proficiency Scales' (2014); Achieve the Core 'focus by grade level' major / supporting / additional cluster guidance for CCSS-aligned weighting. Letter-equivalent band per the AAS / NWEA published 4-point-to-letter conversion convention. School registrar / district administrator governs the transcript letter grade.",
  "standpipe-friction": "Citation: per NFPA 14-2022 (standpipes). Elevation 0.434 psi/ft of water; CQ^2L friction per outlet hose section. AHJ governs. Free at nfpa.org/freeaccess.",
  "standpipe-pdp": "Notice: Departmental SOPs and incident command govern all standpipe and pumping operations. Citation: per NFPA 14-2024 (standpipes) §7. PDP = nozzle pressure + supply friction (NFA CQ^2L) + appliance loss + elevation (0.434 psi/ft). AHJ governs. Free at nfpa.org/freeaccess.",
  "static-pressure-hvac": "Citation: Total external static pressure equals the sum of the pressure drops of each element in the airpath.",
  "static-pressure-piping": "Citation: Pressure from elevation = rho * g * h. For water at 60 F, 1 ft of head ~ 0.433 psi.",
  "statistics-quickread": "Citation: Standard descriptive statistics. Mean = sum/n; sample variance s^2 = sum((x_i - mean)^2)/(n-1); population variance sigma^2 = sum((x_i - mean)^2)/n. The mode list is empty when every value is unique.",
  "steam-pipe-capacity": "Citation: Steam main capacity by continuity - max flow = velocity x 60 x internal area / specific_volume, the area from the Sch 40 ID - the inverse of the steam-main sizer, with the recommended velocity band (supply mains ~6,000 to 12,000 ft/min) per ASHRAE Fundamentals / Systems, by name. The specific volume is read from the saturated-steam table at the line pressure. The velocity band is a recommendation, not a code limit; noise, erosion, and condensate reverse-flow bear on the choice, which the engineer of record governs.",
  "steam-prv-area-for-capacity": "Notice: A sizing aid, not a relief-valve certification; ASME/API and the valve manufacturer govern. Citation: Napier's formula / ASME/API 520 choked steam capacity W = 51.43 x Cd x A x P1 solved for the area: A = W / (51.43 x Cd x P1). Assumes choked flow (P2 < 0.58 x P1); round up to a standard API 526 orifice letter. Saturated steam (superheat needs Ksh); apply the discharge coefficient (~0.6 orifice, ~1 nozzle).",
  "steam-prv-napier": "Notice: A sizing aid, not a relief-valve certification; ASME/API and the valve manufacturer govern. Citation: Napier's formula / ASME/API 520 / Grashof steam orifice / PRV capacity, by name. Choked when P2 < 0.58 x P1; capacity W = 51.43 x Cd x A x P1 (saturated, choked). When choked the capacity depends only on the upstream pressure. Napier is for saturated steam (superheat needs a Ksh factor); a liquid Cv (square-root in pressure drop) is wrong for choked steam, which is linear in P1. Apply the discharge coefficient (~0.6 sharp orifice, ~1 nozzle).",
  "stopping-sight-distance": "Citation: Per AASHTO Green Book (Policy on Geometric Design of Highways and Streets, 7th ed.) Chapter 3 stopping sight distance. AASHTO publishes design SSD tables; this calculator outputs the underlying physics. AHJ (state DOT) governs roadway design. Free at transportation.org for TOC.",
  "storm-shelter": "Citation: FEMA P-320 by name only. No reproduction of figures or text.",
  "stormwater-max-drainage-area": "Citation: Rational method Q = C * i * A solved for the area, A_acres = Q / (C * i) (cfs / in-per-hr / acres). Public engineering practice; runoff coefficients bundled per surface from public engineering tables. A design aid; the AHJ and the civil engineer govern.",
  "stormwater-rational": "Citation: Rational method Q = C * i * A (cfs / acres / in-per-hr). Public engineering practice. Runoff coefficients bundled per surface from public engineering tables.",
  "substrate-for-velocity": "Citation: the Michaelis-Menten equation inverted - [S] = Km x f/(1 - f) for a target fraction f = v/Vmax. At [S] = Km the velocity is half of Vmax; 90% needs 9 x Km, 99% needs 99 x Km. Steady state, substrate in excess of enzyme; the assay conditions govern.",
  "sum-of-years-digits-depreciation": "Citation: GAAP book depreciation - ASC 360 (Property, Plant, and Equipment), by name; sum-of-the-years'-digits accelerated method. Distinct from the macrs-depreciation tile (IRS Pub 946 tax method). Accounting information, not advice; a CPA and current GAAP govern.",
  "superelevation-safe-curve-speed": "Citation: AASHTO point-mass curve model e + f = V^2/(15 R) (A Policy on Geometric Design of Highways and Streets, the Green Book) solved for the speed: V = sqrt( 15 R (e + f) ) mph. The side-friction factor f is from the AASHTO design-speed table and decreases with speed. A design aid, not a substitute for a licensed civil engineer's geometric design.",
  "support-spacing": "Citation: NEC 2023 Chapter 3 securing-and-supporting sections (320.30, 330.30, 334.30, 344.30, 352.30, 358.30), by name. RMC/PVC maximum intervals vary with trade size (the size-specific tables govern). The AHJ governs. Free at nfpa.org/freeaccess.",
  "surety-bond-premium": "Citation: Surety bond premium (tiered rate, surety-industry practice): charged per $1,000 of contract in bands (e.g. $25/$15/$10 per thousand on the first $100k / next $400k / above $500k). The effective rate falls as the contract grows. A budgeting aid; the surety's rate schedule and underwriting govern.",
  "svi-sludge-index": "Citation: Per USEPA Wastewater Operator Training (public domain) and WEF Manual of Practice No. 11 by name. State primacy agency NPDES permit governs effluent limits. Companion F:M ratio in the srt-fm-ratio tile. Free at epa.gov.",
  "sweat-rate-hydration": "Notice: Individual and medical guidance governs all field-hydration decisions. Citation: ACSM / NATA position on fluid replacement, by name. sweat_loss = (pre - post) x 16 + fluid - urine; sweat_rate = sweat_loss / hours; pct_bw_loss = (pre - post) / pre x 100; rehydration = 1.5 x max(0, deficit). A drop of even 2% of body weight degrades performance and judgment. This is fluid volume, not electrolyte replacement.",
  "sweep-width-correction": "Notice: The incident commander and search plan govern all SAR operations; a planning aid, not a promise of detection. Citation: IAMSAR Manual Vol. II / US National SAR Supplement sweep-width correction (W = Wu x f_weather x f_speed x f_fatigue), by name. The uncorrected width comes from published sweep-width tables or a detection-range experiment; the factors come from the published correction tables for the conditions; the corrected width is the W that search-track-spacing expects.",
  "tailstock-setover": "Citation: Lathe tailstock setover for taper turning S = OAL x (D - d) / (2 L), for overall length between centers OAL, taper diameters D and d, and taper length L; first-principles as in Machinery's Handbook (Industrial Press), by name. Suits shallow tapers; a taper attachment or the compound governs steep or precise work.",
  "tanker-fleet-size": "Notice: A planning aid, not incident command; the fill-site capacity and the operation govern. Citation: IFSTA / NFPA 1142 rural water-supply fill-site-limited fleet size, by name. bottleneck_min = max(tank/fill_gpm, tank/dump_gpm); fleet_for_max = ceil(cycle_min / bottleneck_min); site_limited_flow_gpm = tank / bottleneck_min. The bottleneck is the slower fixed site; the flow caps at the tank load over that service time no matter the fleet, so tankers beyond the solved fleet just queue. The tank load is the usable water moved (ISO ~90% of nominal).",
  "tanker-shuttle-cycle": "Notice: A planning aid, not incident command; the fill-site capacity and the operation govern. Citation: IFSTA / NFPA 1142 rural water-supply shuttle cycle time, by name. fill_min = tank_gal / fill_gpm; dump_min = tank_gal / dump_gpm; travel_min = 2 x distance_mi / speed_mph x 60 (round trip); cycle_min = fill + dump + travel; single_tanker_gpm = tank_gal / cycle_min. The travel is the round trip; the tank load is the usable water moved (ISO ~90% of nominal); fill and dump are the site-limited rates. Feed the cycle to tanker-shuttle-flow for the fleet flow.",
  "tanker-shuttle-flow": "Notice: A planning aid, not incident command; the fill-site pump capacity and the operation govern. Citation: ISO PPC hauled-water credit / NFPA 1142 water shuttle, by name. usable = nominal x fraction; shuttle_flow = usable x tankers / cycle (cycle = fill + dump + 2 x travel). ISO credits only about 90% of nominal tank volume, and the fleet flow is capped by the slowest link - usually the fill or dump site, not the tank size.",
  "taper-calc": "Citation: Taper definitions and the taper-per-foot / angle relations - TPF = 12 x (D - d) / L, angle per side = atan((D - d) / 2L) - first-principles trigonometry as in Machinery's Handbook (Industrial Press), by name; public domain.",
  "taping-corrections": "Citation: steel-tape corrections temperature Ct = alpha (T - T0) L (alpha 6.45e-6 /degF), slope Ch = -h^2/(2L), tension Cp = (P - P0) L/(A E), sag Cs = -w^2 L^3/(24 P^2), per the standard surveying references (Ghilani/Wolf), by name. Approximate slope, unsupported sag. A computational aid; the tape calibration governs.",
  "taping-normal-tension": "Citation: normal tension, the pull at which the tension and sag corrections to a suspended steel tape cancel. Derived, not tabulated: setting (P - P0) L / (A E) = w^2 L^3 / (24 P^2) and substituting the span weight W = w L eliminates the length and leaves P^2 (P - P0) = A E W^2 / 24, whose square root is the textbook implicit form P = 0.204 W sqrt(A E) / sqrt(P - P0) (0.204 = 1/sqrt(24)). Solved here by bisection on the cubic. The component corrections match the taping-corrections tile exactly. Steel modulus 29,000,000 psi by default; tape area and weight per foot come from the tape's specification. Does not address temperature or standardization error, and normal tension may exceed a practical or rated pull. A field aid; the tape calibration and the survey's procedure govern.",
  "tdd-ieee-519": "Citation: IEEE 519-2022 Table 1 current-distortion limits (TDD at the PCC): ratio = Isc/IL; limit = 5% (ratio < 20) / 8% (20-50) / 12% (50-100) / 15% (100-1000) / 20% (> 1000); pass if measured TDD <= limit. The limit is on total demand distortion, not THD, and loosens with a stiffer supply. A screening aid; the utility agreement and a measurement study govern.",
  "tds-from-conductivity": "Citation: TDS from conductivity (Standard Methods 2510 / operator practice): TDS (mg/L) = k x EC (uS/cm at 25 C), k commonly 0.55-0.75 by ion makeup. An estimate, not a gravimetric TDS; calibrate k against a lab result. An operations aid; the operator of record and the primacy agency govern compliance.",
  "termination-temp-ampacity": "Citation: NEC 2023 110.14(C) temperature limitations with Table 310.16: the usable ampacity is capped at the lowest-rated termination (60 C at or below 100 A unless listed 75 C, else 75 C; 75 C above 100 A), and the 90 C column is used ONLY for the ambient/fill derating math (derated 90 C = amp_90c x derate), not the final termination current; governing = min(termination column, derated 90 C). The NEC and the equipment listing govern.",
  "thermal-delta-t": "Citation: Original plain-English summaries of typical surface-temperature differentials. NFA / OSHA training generally; not a substitute for vendor-specific imaging guidance.",
  "thermal-expansion-volume": "Citation: Water density vs. temperature, NIST / standard steam tables (public domain). dV = V*(rho_cold/rho_hot - 1), interpolated within 32-212 F. Distinct from the expansion-tank sizing tiles - this outputs the raw expansion volume only. Free at nist.gov.",
  "tile-count": "Citation: tile count = ceil(area_ft^2 * 144 / (w*h)) plus waste; grout volume estimated from joint perimeter * width * tile thickness.",
  "timesheet": "Citation: Standard payroll math; reuses overtime utility logic and IRS standard mileage rate.",
  "tip-out": "Citation: each member's share = (their hours / total hours) * total amount.",
  "tolerance-stack-rss": "Citation: Tolerance stack-up (mechanical design / GD&T practice): worst-case tolerance = sum of the half-widths, RSS (statistical) tolerance = sqrt(sum of squares). RSS assumes centered, independent, normally distributed dimensions. A design aid; the drawing tolerances and the assembly's criticality govern.",
  "tool-maintenance": "Citation: Original plain-English maintenance schedule for common trades tools. Manufacturer documentation governs for specific tools.",
  "tpr-discharge": "Citation: IPC 2021 Section 504 (504.4 valve rating vs heater input, 504.6 discharge piping) and ANSI Z21.22 / CSA 4.4 by name. The discharge line is the full valve outlet, never reduced.",
  "transformer-conductor-protection": "Citation: Transformer primary/secondary full-load current and the overcurrent-protection maxima per NEC Table 450.3(B), with the secondary-conductor tap rules of NEC 240.21(C), by name. A computational aid for the <= 1000 V case; the AHJ-adopted NEC edition and the design engineer govern. Free at nfpa.org/freeaccess.",
  "transformer-inrush-point": "Citation: transformer energization-inrush coordination (IEEE C57.109; NEC 450.3 context): FLA = kVA x 1000 / (sqrt(3) x V) three-phase; inrush point = multiple x FLA at the stated duration (~12x at 0.1 s, up to 25x at 0.01 s). The primary device curve must sit right of the inrush point and left of the damage curve. A design aid; the manufacturer's inrush data and a coordination study govern.",
  "transformer-k-factor": "Citation: UL 1561 / IEEE C57.110 K-factor = sum(Ih^2 x h^2) / sum(Ih^2), harmonics in per-unit of the fundamental; round up to the next standard K-rating (K-1/K-4/K-9/K-13/K-20/K-30/K-40). The measured spectrum and the manufacturer govern.",
  "transformer-kva-sizing": "Citation: Per ANSI/IEEE C57 standard kVA step series. FLA = kVA * 1000 / (V * sqrt(phases)).",
  "transformer-loading-efficiency": "Citation: Transformer loading efficiency (first-principles): output = kVA x load x PF; loss = (no-load + load^2 x full-load loss); efficiency = output / (output + loss); peak efficiency at load = sqrt(no-load / full-load loss). A design/screening aid; the manufacturer's test report governs.",
  "transformer-voltage-regulation": "Citation: Transformer voltage-regulation approximation (from %R, %X, and load power factor): VR% = load x (%R cos + %X sin) + load^2 x (%X cos - %R sin)^2 / 200, sin negative for a leading power factor. An IEEE C57 test-report quantity; %Z alone does not give it because it depends on the %R / %X split and the power factor. Terminal regulation, not the feeder drop. A design aid; the utility's voltage study governs.",
  "trap-arm": "Citation: Standard trap-arm length table (public plumbing engineering practice). The trap weir must not drain through the vent; total fall limited to one pipe diameter.",
  "traverse-closure": "Citation: Latitude/departure traverse and compass-rule (Bowditch) adjustment per FM 5-233 Construction Surveying (public-domain US Government work) and standard surveying references. The recorded plat and surveyor of record govern; this is a field estimate.",
  "tree-crz-encroachment": "Citation: critical root zone encroachment (ANSI A300 Part 5 tree protection; arboriculture practice), by name. radius = radius_factor x DBH; the construction limit line at distance d cuts a segment R^2 x acos(d/R) - d x sqrt(R^2 - d^2); encroach = segment / (pi x R^2) x 100. Species thresholds (Matheny & Clark tolerance): tolerant ~40%, intermediate ~30%, sensitive ~20%. The encroachment is for a single straight limit line; a real footprint may cut more than one side and the impacts are cumulative. The CRZ is set by the trunk, not the canopy.",
  "tree-protection-zone": "Citation: tree protection zone / critical root zone (ANSI A300 Part 5; ISA critical root zone), by name. radius = radius_factor x DBH; area = pi x radius^2. Factors: 1.0 ft per in of DBH (standard), 1.5 ft per in (conservative / mature). The zone is set by the trunk, not the canopy dripline; protection is cumulative (fence plus no grade change, compaction, or trenching). A qualified arborist and the local ordinance govern.",
  "triage-quickread": "Citation: START triage categories by name only. Original plain-English summary.",
  "truss-capacity": "Notice: Verify with the truss manufacturer's published load chart and a qualified rigger. Touring and entertainment rigging is governed by ANSI E1.21 and the venue's competent person.",
  "turning-surface-finish": "Citation: Theoretical surface roughness from feed and nose radius - Rt = f^2 / (8 x r), Ra ~= Rt / 4 - first-principles scallop geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The measured finish is rougher than this theoretical value.",
  "unit-converter": "Citation: NIST SP 811 unit factors. Temperature handled affinely (C/F/K/R).",
  "units-of-production-depr": "Citation: units-of-production (activity) depreciation (GAAP; IRS Pub 946 activity method): rate = (cost - salvage) / total_units; period_depreciation = rate x period_units; book_value = max(cost - rate x accumulated_units, salvage). Depreciation tracks usage, so an idle asset takes zero; book value is floored at salvage. A GAAP/book method, not tax MACRS. A bookkeeping aid; the accounting policy and tax rules govern.",
  "vacuum-lift-reading": "Notice: A readout aid, not incident command; the pump operator and incident command govern. Citation: IFSTA / NWCG fire-pump drafting practice vacuum-to-lift conversion, by name. suction_head_ft = vacuum_inhg x 1.13; theoretical_ceiling = 33.9 - elevation/1000; attainable_ceiling = factor x theoretical (factor about 2/3); margin = attainable - suction_head. At steady flow the compound gauge reads the lift plus the suction-hose friction, so the readout is total suction head; a reading approaching the ceiling means the pump is about to lose prime and cavitate.",
  "velocity-head": "Citation: velocity head h_v = V^2/(2g) (g = 32.2 ft/s^2) and dynamic pressure q = 1/2 rho V^2, first-principles fluid mechanics. Both scale with V^2. The code velocity limits (~5-8 ft/s water) and the engineer of record govern.",
  "vent-sizing-stack": "Citation: Per the adopted plumbing code's vent sizing and length provisions (IPC Chapter 9 / UPC Chapter 9, by name). Table values user-supplied; the AHJ-adopted edition governs. Developed length excludes fitting equivalents; wet-vent configurations out of scope. Code library free read-only at codes.iccsafe.org.",
  "vertical-curve": "Citation: Equal-tangent vertical curve per AASHTO A Policy on Geometric Design of Highways and Streets (the Green Book) and FM 5-233 Construction Surveying, from first-principles parabolic geometry. The design of record and engineer of record govern.",
  "vertical-curve-sight-distance": "Citation: AASHTO crest vertical-curve minimums per A Policy on Geometric Design of Highways and Streets (the Green Book): L = A S^2 / C for S <= L and L = 2 S - C/A for S > L, with C = 2158 (SSD crest; a 3.5 ft eye and 2.0 ft object height) or 2800 (passing); K = L/A. This is the crest SSD control -- sag curves use headlight/comfort/drainage criteria. A design aid, not a substitute for a licensed civil engineer's design.",
  "vfd-reflected-wave": "Citation: VFD reflected-wave cable-length limit (NEMA MG-1 Part 31; transmission-line reflection): cable_velocity = 0.01 x velocity_pct x 984; L_crit = rise_time x cable_velocity / 2; V_bus = sqrt(2) x V_LL; V_peak = 2 V_bus past L_crit; limits 3.1 x V_LL (inverter-duty) and ~1000 V (general-purpose). The limit is the drive rise time, not the horsepower. The fix is a dV/dt filter or an inverter-duty motor. The drive and motor data govern.",
  "vibration-isolation": "Citation: ASHRAE Handbook -- Fundamentals, Sound and Vibration (single-DOF isolator). Natural frequency fn = 3.13/sqrt(static deflection in inches) Hz; disturbing frequency = rpm/60; transmissibility T = 1/|(f/fn)^2 - 1|; isolation efficiency = (1 - T). Isolation needs a frequency ratio over sqrt(2) = 1.414, else the mount amplifies (resonance at 1). Undamped idealization; the rated isolator deflection under load governs. A design aid, not a stamped vibration-isolation design.",
  "walk-in-cooler-load": "Citation: Walk-in cooler heat load (ASHRAE Refrigeration / box-load practice): transmission = U x area x deltaT, plus infiltration + product + internal loads, times a safety factor (~1.10). Size the evaporator for an ~18-hour run. A sizing aid; the box-load method and equipment ratings govern.",
  "water-classes": "Citation: Original plain-English summaries by the project author. References IICRC S500 by name; the standard text is not reproduced.",
  "water-hammer-surge": "Citation: Joukowsky equation by name. Pipe-fluid coupling via celerity formula. Rapid closure flagged when t_close < 2L/a.",
  "water-supply-duration": "Citation: Volume/flow continuity (first principles). Required-duration context per NFPA 1142 (rural/suburban water supply), by name. Distinct from nfpa-1142-water-supply (which sizes required supply from the structure) and scba-cylinder-time (air, not water). NFPA 1142 free read-only at nfpa.org/freeaccess.",
  "weld-deposit-composition": "Citation: diluted weld-deposit composition, the standard welding-metallurgy mixing rule (by name): deposit% = D x base% + (1 - D) x filler%, with D the dilution fraction from the weld-dilution tile. One element, one pass, well-mixed pool; microstructure and ferrite come from a Schaeffler/WRC diagram, not this. The WPS, the filler certs, and the base-metal MTR govern.",
  "weld-duty-cycle": "Citation: The inverse-square duty-cycle relation (NEMA EW-1 arc-welding power-source convention), by name; first-principles I^2-heating, public domain. Duty cycle is measured over a 10-minute window; exceeding it trips the thermal overload.",
  "weld-preheat-fuel": "Citation: specific heat of carbon steel (about 0.11 Btu/lb-degF) and the heating value of propane (about 21,600 Btu/lb, 91,500 Btu/gal), by name. Heat = mass x specific heat x temperature rise; fuel = heat / efficiency. Hot-work hazards govern; follow the maker's instructions and your site's hot-work permit. Preheat temperature comes from carbon-equivalent or the WPS.",
  "well-drawdown": "Citation: drawdown = pumping level - static level; specific capacity = discharge / drawdown (GPM per ft); recommended pump setting = pumping level + offset (default 20 ft). Per the AWWA A100 (Water Wells) standard and USGS well-testing methods (Open-File Report 02-197). Free at awwa.org for the A100 TOC and pubs.usgs.gov.",
  "well-max-yield": "Citation: sustainable well yield from specific capacity: max_yield = specific_capacity x allowable_drawdown (GPM). Specific capacity (GPM per ft) from a step-drawdown test or the well-drawdown tile; the allowable drawdown is static level to a safe level above the pump intake. Per AWWA A100 and USGS well-testing methods; a constant-rate test governs. Free at awwa.org / pubs.usgs.gov.",
  "wet-bulb-psychrometer": "Citation: Standard psychrometric wet-bulb relation e = e_s(Tw) - A * P * (Td - Tw); A ~ 0.000662 1/C at sea level.",
  "wh-expansion-tank": "Citation: expansion factor = (rho_cold - rho_hot) / rho_hot from public steam-table densities; V_expansion = heater volume x factor; V_tank = V_expansion / acceptance factor. Per the ASPE Plumbing Engineering Design Handbook (2nd ed.) Ch. 6 and ASME B40.1. Pre-charge equals incoming pressure. AHJ governs. Free at aspe.org.",
  "wire-ampacity": "Citation: a physics-based ESTIMATE, not a table lookup. This tile solves a steady-state thermal balance (I^2 R heating against convective and radiative loss from the conductor surface) with the effective coefficient calibrated to a 75 C THWN #12 in 30 C ambient, then applies the NEC 310.15(C)(1) conductor-count adjustment. It is NOT NEC 2023 Table 310.16: the free-air model scales roughly as area^0.75, so it reads progressively HIGH against the table as the conductor gets larger, and reading high on ampacity means undersizing the wire. Size conductors from NEC 2023 Table 310.16 in the AHJ-adopted edition; for table-based work use the ambient/fill adjustment tile, which takes the Table 310.16 ampacity as an input. Free at nfpa.org/freeaccess.",
  "workers-comp-emr-premium": "Citation: Workers-comp premium and experience mod (NCCI / state rating-bureau practice): manual premium = payroll/100 x class rate, actual premium = manual x EMR (an EMR below 1.0 is a credit, above 1.0 a debit). A budgeting aid; the rating bureau's EMR and the insurer's rates govern.",
  "working-space-110-26": "Citation: NEC 2023 110.26(A) (working space) and 110.26(E) (dedicated equipment space) - the depth by voltage-to-ground and condition, the 30 in (or equipment-width) clearance, and the 6.5 ft headroom, with a required 90-degree door swing. The AHJ governs. Free at nfpa.org/freeaccess.",
};
